window.POEM_DB=window.POEM_DB||{};POEM_DB["sui_000"]={"n":"无名氏","dyn":"隋","poems":[{"t":"紫骝马歌辞 其三","f":"五言绝句","c":["十五从军征，八十始得归。","道逢乡里人，家中有阿谁。"]},{"t":"碧玉歌 其二","f":"五言绝句","c":["碧玉小家女，不敢攀贵德。","感郎千金意，惭无倾城色。"]},{"t":"企喻歌 其一","f":"五言绝句","c":["男儿欲作健，结伴不须多。","鹞子经天飞，群雀两向波。"]},{"t":"企喻歌 其四","f":"五言绝句","c":["男儿可怜虫，出门怀死忧。","尸丧狭谷中，白骨无人收。"]},{"t":"西乌夜飞 其一","f":"五言绝句","c":["日从东方出，团团鸡子黄。","夫妇恩情重，怜欢故在傍。"]},{"t":"西乌夜飞 其四","f":"五言绝句","c":["阳春二三月，诸花尽芳盛。","持底唤欢来，花笑莺歌咏。"]},{"t":"折杨柳歌辞 其五","f":"五言绝句","c":["健儿须快马，快马须健儿。","䟤跋黄尘下，然后别雄雌。"]},{"t":"幽州马客吟歌辞 其一","f":"五言绝句","c":["快马常苦瘦，剿儿常苦贫。","黄禾起羸马，有钱始作人。"]},{"t":"读曲歌八十九首 其八十一","f":"五言绝句","c":["一夕就郎宿，通夜语不息。","黄蘖万里路，道苦真无极。"]},{"t":"读曲歌八十九首 其二十九","f":"古风","c":["奈何许。","石阙生口中。","衔碑不得语。"]},{"t":"读曲歌八十九首 其四十七","f":"五言绝句","c":["思欢不得来，抱被空中语。","月没星不亮，持底明侬绪。"]},{"t":"读曲歌八十九首 其十五","f":"五言绝句","c":["柳树得春风，一低复一昂。","谁能空相忆，独眠度三阳。"]},{"t":"读曲歌八十九首 其八十二","f":"五言绝句","c":["登店卖三葛，郎来买丈馀。","合匹与郎去，谁解断粗疏。"]},{"t":"读曲歌八十九首 其十六","f":"古风","c":["折杨柳。","百鸟园林啼。","道欢不离口。"]},{"t":"敕勒歌","f":"古风","c":["敕勒川。","阴山下。","天似穹庐。","笼盖四野。","天苍苍。","野茫茫。","风吹草低见牛羊。"]},{"t":"琅琊王歌辞 其一","f":"五言绝句","c":["新买五尺刀，悬著中梁柱。","一日三摩娑，剧于十五女。"]},{"t":"陇头流水歌 其一","f":"古风","c":["陇头流水，流离西下。","念吾一身，飘然旷野。"]},{"t":"五音曲 其五 羽引","f":"古风","c":["玄英纪运。","冬冰折。","物为音本。","和且悦。","穷高测深。","长无绝。"]},{"t":"五音曲 其一 角引","f":"古风","c":["萌生触发。","岁在春。","咸池始奏。","德尚仁。","惉懘以息。","和且均。"]},{"t":"五音曲 其三 宫引","f":"古风","c":["八音资始。","君五声。","兴此和乐。","感百精。","优游律吕。","被咸英。"]},{"t":"五音曲 其四 商引","f":"古风","c":["司秋纪兑。","奏西音。","激扬钟石。","和瑟琴。","风流福被。","乐愔愔。"]},{"t":"五音曲 其二 徵引","f":"古风","c":["执衡司事。","宅离方。","滔滔夏日。","火德昌。","八音备举。","乐无疆。"]},{"t":"折杨柳歌辞 其四","f":"五言绝句","c":["遥看孟津河，杨柳郁婆娑。","我是虏家儿，不解汉儿歌。"]},{"t":"石城乐 其五","f":"五言绝句","c":["闻欢远行去，相送方山亭。","风吹黄蘖藩，恶闻苦篱声。"]},{"t":"华山畿二十五首 其七","f":"古风","c":["啼著曙。","泪落枕将浮。","身沉被流去。"]},{"t":"华山畿二十五首 其一","f":"古风","c":["华山畿。","君既为侬死。","独活为谁施。","欢若见怜时。","棺木为侬开。"]},{"t":"华山畿二十五首 其二十","f":"古风","c":["奈何许。","天下人何限。","慊慊只为汝。"]},{"t":"读曲歌八十九首 其二十一","f":"古风","c":["逋发不可料。","憔悴为谁睹。","欲知相忆时。","但看裙带缓几许。"]},{"t":"读曲歌八十九首 其五十五","f":"古风","c":["打杀长鸣鸡。","弹去乌臼鸟。","愿得连冥不复曙。","一年都一晓。"]},{"t":"襄阳乐 其七","f":"五言绝句","c":["女萝自微薄，寄托长松表。","何惜负霜死，贵得相缠绕。"]},{"t":"作蚕丝 其二","f":"五言绝句","c":["春蚕不应老，昼夜常怀丝。","何惜微躯尽，缠绵自有时。"]},{"t":"乌夜啼 其一","f":"五言绝句","c":["歌舞诸少年，娉婷无穜迹。","菖蒲花可怜，闻名不曾识。"]},{"t":"石城乐 其一","f":"五言绝句","c":["生长石城下，开窗对城楼。","城中诸少年，出入见依投。"]},{"t":"杨叛儿 其二","f":"五言绝句","c":["暂出白门前，杨柳可藏乌。","郎作沈水香，侬作博山炉。"]},{"t":"襄阳乐 其一","f":"五言绝句","c":["朝发襄阳城，暮至大堤宿。","大堤诸女儿，花艳惊郎目。"]},{"t":"苏小小歌","f":"五言绝句","c":["妾乘油壁车，郎骑青骢马。","何处结同心，西陵松柏下。"]},{"t":"广平百姓为李波小妹语","f":"古风","c":["李波小妹字雍容。","褰裙逐马如卷蓬。","左射右射必叠双。","妇女尚如此。","男子那可逢。"]},{"t":"送别诗","f":"七言绝句","c":["杨柳青青著地垂，杨花漫漫搅天飞。","柳条折尽花飞尽，借问行人归不归。"]},{"t":"炀帝幸江南时闻民歌","f":"五言古诗","c":["我儿征辽东，饿死青山下。","今我挽龙舟，又困随堤道。","方今天下饥，路粮无些小。","前去三千程，此身安可保。","寒骨枕荒沙，幽魂泣烟草。","悲损门内妻，望断吾家老。","安得义男儿，焚此无主尸。","引其孤魂回，负其白骨归。"]},{"t":"乌夜啼 其二","f":"五言绝句","c":["长樯铁鹿子，布帆阿那起。","诧侬安在间，一去数千里。"]},{"t":"时人为檀道济歌","f":"五言古诗","c":["可怜白浮鸠。","枉杀檀江州。"]},{"t":"时人为檀道济歌","f":"五言古诗","c":["生人作死别，荼毒当奈何。"]},{"t":"读曲歌","f":"五言古诗","c":["死罪刘领军，误杀刘第四。"]},{"t":"刘敬叔引诗","f":"五言古诗","c":["鸡山别飞响，雉涧和清音。"]},{"t":"民间为谢灵运谣","f":"五言古诗","c":["四人挈衣裙，三人捉坐席。"]},{"t":"元嘉中魏地童谣","f":"七言绝句","c":["轺车北来如穿雉。","不意虏马饮江水。","虏主北归石济死。","虏欲渡江天不徙。"]},{"t":"臧质引童谣","f":"五言古诗","c":["虏马渡江水，佛狸死卯年。"]},{"t":"元嘉末童谣","f":"五言古诗","c":["钱唐出天子。"]},{"t":"民间为奚显度谣","f":"古风","c":["宁得建康压额。","不能受奚度拍。"]},{"t":"泰始中童谣","f":"五言古诗","c":["东城出天子。"]},{"t":"永光初谣言","f":"五言古诗","c":["湘州出天子。"]},{"t":"元徽中童谣","f":"五言古诗","c":["襄阳白铜蹄。","郎杀荆州儿。"]},{"t":"东阳为释慧约谣","f":"七言古诗","c":["少达妙理娄居士。"]},{"t":"时人为刘劭刘骏语","f":"五言绝句","c":["遥望建康城，江水逆流萦。","前见子杀父，后见弟杀兄。"]},{"t":"麦城俗谚","f":"古风","c":["东驴西磨。","麦城自破。"]},{"t":"颜延之引谚","f":"古风","c":["富则盛。","贫则病。"]},{"t":"清溪谚","f":"古风","c":["扬州青。","是鬼营。"]},{"t":"释慧通引谚","f":"古风","c":["指南为北，自谓不惑。","指西为东，自谓不蒙。"]},{"t":"时人为丁旿语","f":"古风","c":["勿跋扈。","付丁旿。"]},{"t":"南豫州军士为王玄谟宗越语","f":"五言绝句","c":["宁作五年徒，不逢王玄谟。","玄谟犹尚可，宗越更杀我。"]},{"t":"鼓山俗语","f":"古风","c":["南彭北鼓。","相去十五。"]},{"t":"京邑为何勖孟灵休语","f":"古风","c":["安成食。","临汝饰。"]},{"t":"时人为王延之王僧虔语","f":"古风","c":["二王居平。","不送不迎。"]},{"t":"京师为东安斗场二寺僧语","f":"五言古诗","c":["斗场禅师窟，东安谈义林。"]},{"t":"时人为胡母颢语","f":"五言古诗","c":["禾绢闭眼诺。","胡母大张橐。"]},{"t":"百姓为袁粲褚彦回语","f":"五言古诗","c":["可怜石头城。","宁为袁粲死。","不作褚渊生。"]},{"t":"齐宋以来民间语","f":"五言古诗","c":["扰攘建武上。"]},{"t":"时人评八僧语","f":"五言绝句","c":["生睿发天真，严观洼流得。","慧义彭亨进，寇渊千默塞。"]},{"t":"时人为释道经慧静语","f":"五言绝句","c":["洛下长大耳，东阿黑如墨。","有问无不酬，有酬无不塞。"]},{"t":"碧玉歌 其一","f":"五言绝句","c":["碧玉破瓜时，郎为情颠倒。","芙蓉陵霜荣，秋容故尚好。"]},{"t":"华山畿二十五首 其二","f":"五言绝句","c":["闻欢大养蚕，定得几许丝。","所得何足言，奈何黑瘦为。"]},{"t":"华山畿二十五首 其三","f":"古风","c":["夜相思。","投壶不得箭。","忆欢作娇时。"]},{"t":"华山畿二十五首 其四","f":"五言古诗","c":["开门枕水渚。","三刀治一鱼。","历乱伤杀汝。"]},{"t":"华山畿二十五首 其五","f":"五言古诗","c":["未敢便相许。","夜闻侬家论。","不持侬与汝。"]},{"t":"华山畿二十五首 其六","f":"五言古诗","c":["懊恼不堪止。","上床解要绳。","自经屏风里。"]},{"t":"华山畿二十五首 其八","f":"古风","c":["将懊恼。","石阙昼夜题。","碑泪常不燥。"]},{"t":"华山畿二十五首 其九","f":"五言古诗","c":["别后常相思。","顿书千丈阙。","题碑无罢时。"]},{"t":"华山畿二十五首 其十","f":"古风","c":["奈何许。","所欢不在间。","娇笑向谁绪。"]},{"t":"华山畿二十五首 其十一","f":"古风","c":["隔津欢。","牵牛语织女。","离泪溢河汉。"]},{"t":"华山畿二十五首 其十二","f":"古风","c":["啼相忆。","泪如漏刻水。","昼夜流不息。"]},{"t":"华山畿二十五首 其十三","f":"五言古诗","c":["著处多遇罗。","的的往年少。","艳情何能多。"]},{"t":"华山畿二十五首 其十四","f":"五言古诗","c":["无故相然我。","路绝行人断。","夜夜故望汝。"]},{"t":"华山畿二十五首 其十五","f":"五言古诗","c":["一坐复一起。","黄昏人定后。","许时不来已。"]},{"t":"华山畿二十五首 其十六","f":"古风","c":["摩可浓。","巷巷相罗截。","终当不置汝。"]},{"t":"华山畿二十五首 其十七","f":"五言古诗","c":["不能久长离。","中夜忆欢时。","抱被空中啼。"]},{"t":"华山畿二十五首 其十八","f":"五言古诗","c":["腹中如汤灌。","肝肠寸寸断。","教侬底聊赖。"]},{"t":"华山畿二十五首 其十九","f":"五言古诗","c":["相送劳劳渚。","长江不应满。","是侬泪成许。"]},{"t":"华山畿二十五首 其二十一","f":"五言古诗","c":["郎情难可道。","欢行豆挟心。","见荻多欲绕。"]},{"t":"华山畿二十五首 其二十二","f":"古风","c":["松上萝。","愿君如行云。","时时见经过。"]},{"t":"华山畿二十五首 其二十三","f":"古风","c":["夜相思。","风吹窗帘动。","言是所欢来。"]},{"t":"华山畿二十五首 其二十四","f":"古风","c":["长鸣鸡。","谁知侬念汝。","独向空中啼。"]},{"t":"华山畿二十五首 其二十五","f":"五言古诗","c":["腹中如乱丝。","愦愦适得去。","愁毒已复来。"]},{"t":"读曲歌八十九首 其一","f":"五言绝句","c":["花钗芙蓉髻，双鬓如浮云。","春风不知著，好来动罗裙。"]},{"t":"读曲歌八十九首 其二","f":"五言古诗","c":["念子情难有。","已恶动罗裙。","斩侬入怀不。"]},{"t":"读曲歌八十九首 其三","f":"五言绝句","c":["红蓝与芙蓉，我色与欢敌。","莫案石榴花，历乱听侬摘。"]},{"t":"读曲歌八十九首 其四","f":"五言绝句","c":["千叶红芙蓉，照灼绿水边。","馀花任郎摘，慎莫罢侬连。"]},{"t":"读曲歌八十九首 其五","f":"古风","c":["思欢久。","不爱独枝莲。","只惜同心藕。"]},{"t":"读曲歌八十九首 其六","f":"五言绝句","c":["打坏木栖床，谁能坐相思。","三更书石阙，忆子夜啼碑。"]},{"t":"读曲歌八十九首 其七","f":"五言古诗","c":["奈何不可言。","朝看莫牛迹。","知是宿蹄痕。"]},{"t":"读曲歌八十九首 其八","f":"五言绝句","c":["娑拖何处归，道逢播掿郎。","口朱脱去尽，花钗复低昂。"]},{"t":"读曲歌八十九首 其九","f":"古风","c":["所欢子。","莲从胸上度。","刺忆庭欲死。"]},{"t":"读曲歌八十九首 其十","f":"古风","c":["揽裳踱。","跣把丝织履。","故交白足露。"]},{"t":"读曲歌八十九首 其十一","f":"古风","c":["上知所。","所欢不见怜。","憎状从前度。"]},{"t":"读曲歌八十九首 其十二","f":"古风","c":["思难忍。","络罂语犹壶。","倒写侬顿尽。"]},{"t":"读曲歌八十九首 其十三","f":"五言绝句","c":["上树摘桐花，何悟枝枯燥。","迢迢空中落，遂为梧子道。"]},{"t":"读曲歌八十九首 其十七","f":"五言绝句","c":["縠衫两袖裂，花钗鬓边低。","何处分别归，西上古馀啼。"]},{"t":"读曲歌八十九首 其十八","f":"古风","c":["所欢子。","不与他人别。","啼是忆郎耳。"]},{"t":"读曲歌八十九首 其十九","f":"五言绝句","c":["披被树明灯，独思谁能忍。","欲知长寒夜，兰灯倾壶尽。"]},{"t":"读曲歌八十九首 其二十","f":"五言古诗","c":["坐起叹汝好。","愿他甘丛香。","倾筐入怀抱。"]},{"t":"读曲歌八十九首 其二十二","f":"五言古诗","c":["忆欢不能食。","徘徊三路间。","因风觅消息。"]},{"t":"读曲歌八十九首 其二十三","f":"五言绝句","c":["朝日光景开，从君良燕游。","愿如卜者策，长与千岁龟。"]},{"t":"读曲歌八十九首 其二十四","f":"古风","c":["所欢子。","问春花可怜。","括插袮裆里。"]},{"t":"读曲歌八十九首 其二十五","f":"五言绝句","c":["芳萱初生时，知是无忧草。","双眉画未成，那能就郎抱。"]},{"t":"读曲歌八十九首 其二十六","f":"古风","c":["百花鲜。","谁能怀春日。","独入罗帐眠。"]},{"t":"读曲歌八十九首 其二十七","f":"古风","c":["闻欢得新侬。","四支懊如垂。","鸟散放行路。","井中百翅不能飞。"]},{"t":"读曲歌八十九首 其二十八","f":"五言绝句","c":["怜欢敢唤名，念欢不呼字。","连唤欢复欢，两誓不相弃。"]},{"t":"读曲歌八十九首 其三十","f":"古风","c":["白门前。","乌帽白帽来。","白帽郎是侬。","良不知乌帽郎是谁。"]},{"t":"读曲歌八十九首 其三十一","f":"五言绝句","c":["初阳正二月，草木郁青青。","蹑履步前园，时物感人情。"]},{"t":"读曲歌八十九首 其三十二","f":"五言绝句","c":["青幡起御路，绿柳荫驰道。","欢赠玉树筝，侬送千金宝。"]},{"t":"读曲歌八十九首 其三十三","f":"五言绝句","c":["桃花落已尽，秋思犹未央。","春风难期信，托情明月光。"]},{"t":"读曲歌八十九首 其三十四","f":"五言绝句","c":["计约黄昏后，人断犹未来。","闻欢开方局，已复将谁期。"]},{"t":"读曲歌八十九首 其三十五","f":"五言绝句","c":["自从别郎后，卧宿头不举。","飞龙落药店，骨出只为汝。"]},{"t":"读曲歌八十九首 其三十六","f":"五言绝句","c":["日光没已尽，宿鸟纵横飞。","徙倚望行云，躞蹀待郎归。"]},{"t":"读曲歌八十九首 其三十七","f":"五言绝句","c":["百度不一回，千书信不归。","春风吹杨柳，华艳空徘徊。"]},{"t":"读曲歌八十九首 其三十八","f":"五言绝句","c":["音信阔弦朔，方悟千里遥。","朝霜语白日，知我为欢消。"]},{"t":"读曲歌八十九首 其三十九","f":"五言绝句","c":["合冥过藩来，向晓开门去。","欢取身上好，不为侬作虑。"]},{"t":"读曲歌八十九首 其四十","f":"五言绝句","c":["五鼓起开门，正见欢子度。","何处宿行还，衣被有霜露。"]},{"t":"读曲歌八十九首 其四十一","f":"五言绝句","c":["本自无此意，谁交郎举前。","视侬转迈迈，不复来时言。"]},{"t":"读曲歌八十九首 其四十二","f":"五言绝句","c":["自我别欢后，叹音不绝响。","茱萸持捻泥，龛有杀子像。"]},{"t":"读曲歌八十九首 其四十三","f":"五言绝句","c":["家贫近店肆，出入引长事。","郎君不浮华，谁能呈实意。"]},{"t":"读曲歌八十九首 其四十四","f":"五言绝句","c":["念日行不遇，道逢播掿郎。","查灭衣服坏，白肉亦黯疮。"]},{"t":"读曲歌八十九首 其四十五","f":"五言绝句","c":["歔欷暗中啼，斜日照帐里。","无油何所苦，但使天明尔。"]},{"t":"读曲歌八十九首 其四十六","f":"五言绝句","c":["黄丝咡素琴，泛弹弦不断。","百弄任郎作，唯莫广陵散。"]},{"t":"读曲歌八十九首 其四十八","f":"五言绝句","c":["诈我不出门，冥就他侬宿。","鹿转方相头，丁倒欺人目。"]},{"t":"读曲歌八十九首 其四十九","f":"五言绝句","c":["欢但且还去，遗信相参伺。","契儿向高店，须臾侬自来。"]},{"t":"读曲歌八十九首 其五十","f":"五言绝句","c":["欲行一过心，谁我道相怜。","摘菊持饮酒，浮华著口边。"]},{"t":"读曲歌八十九首 其五十一","f":"五言绝句","c":["语我不游行，常常走巷路。","败桥语方相，欺侬那得度。"]},{"t":"读曲歌八十九首 其五十二","f":"五言绝句","c":["阔面行负情，诈我言端的。","画背作天图，子将负星历。"]},{"t":"读曲歌八十九首 其五十三","f":"五言绝句","c":["君行负怜事，那得厚相于。","麻纸语三葛，我薄汝粗疏。"]},{"t":"读曲歌八十九首 其五十四","f":"五言绝句","c":["黄天不灭解，甲夜曙星出。","漏刻无心肠，复令五更毕。"]},{"t":"读曲歌八十九首 其五十六","f":"古风","c":["空中人。","住在高樯深閤里。","书信了不通。","故使风往尔。"]},{"t":"读曲歌八十九首 其五十七","f":"五言绝句","c":["侬心常慊慊，欢行由豫情。","雾露隐芙蓉，见莲讵分明。"]},{"t":"读曲歌八十九首 其五十八","f":"五言绝句","c":["非欢独慊慊，侬意亦驱驱。","双灯俱时尽，奈许两无由。"]},{"t":"读曲歌八十九首 其五十九","f":"五言绝句","c":["谁交强缠绵，常持罢作虑。","作生隐藕叶，莲侬在何处。"]},{"t":"读曲歌八十九首 其六十","f":"五言绝句","c":["相怜两乐事，黄作无趣怒。","合散无黄连，此事复何苦。"]},{"t":"读曲歌八十九首 其六十一","f":"五言绝句","c":["谁交强缠绵，常持罢作意。","走马织悬帘，薄情奈当驶。"]},{"t":"读曲歌八十九首 其六十三","f":"五言绝句","c":["百忆却欲噫，两眼常不燥。","蕃师五鼓行，离侬何太早。"]},{"t":"读曲歌八十九首 其六十四","f":"五言绝句","c":["含笑来向侬，一抱不能置。","领后千里带，那顿谁多媚。"]},{"t":"读曲歌八十九首 其六十五","f":"古风","c":["欢相怜。","今去何时来。","裲裆别去年。","不忍见分题。"]},{"t":"读曲歌八十九首 其六十六","f":"古风","c":["欢相怜。","题心共饮血。","流头入黄泉。","分作两死计。"]},{"t":"读曲歌八十九首 其六十七","f":"五言绝句","c":["娇笑来向侬，一抱不能已。","湖燥芙蓉萎，莲汝藕欲死。"]},{"t":"读曲歌八十九首 其六十八","f":"五言绝句","c":["欢心不相怜，慊苦竟何已。","芙蓉腹里萎，莲汝从心起。"]},{"t":"读曲歌八十九首 其六十九","f":"五言绝句","c":["下帷掩灯烛，明月照帐中。","无油何所苦，但使天明侬。"]},{"t":"读曲歌八十九首 其七十","f":"五言绝句","c":["执手与欢别，欲去情不忍。","馀光照已藩，坐见离日尽。"]},{"t":"读曲歌八十九首 其七十一","f":"五言绝句","c":["种莲长江边，藕生黄蘖浦。","必得莲子时，流离经辛苦。"]},{"t":"读曲歌八十九首 其七十二","f":"五言绝句","c":["人传我不虚，实情明把纳。","芙蓉万层生，莲子信重沓。"]},{"t":"读曲歌八十九首 其七十三","f":"五言绝句","c":["闻乖事难怀，况复临别离。","伏龟语石板，方作千岁碑。"]},{"t":"读曲歌八十九首 其七十四","f":"五言绝句","c":["钤荡与时竞，不得寻倾虑。","春风扇芳条，常念花落去。"]},{"t":"读曲歌八十九首 其七十五","f":"五言绝句","c":["坐倚无精魂，使我生百虑。","方局十七道，期会是何处。"]},{"t":"读曲歌八十九首 其七十七","f":"五言绝句","c":["十期九不果，常抱怀恨生。","然灯不下炷，有油那得明。"]},{"t":"读曲歌八十九首 其七十八","f":"五言绝句","c":["自从近日来，了不相寻博。","竹帘裲裆题，知子心情薄。"]},{"t":"读曲歌八十九首 其七十九","f":"五言绝句","c":["下帷灯火尽，朗月照怀里。","无油何所苦，但今天明尔。"]},{"t":"读曲歌八十九首 其八十","f":"五言绝句","c":["近日莲违期，不复寻博子。","六筹翻双鱼，都成罢去已。"]},{"t":"读曲歌八十九首 其八十三","f":"五言古诗","c":["侬亦粗经风。","罢顿葛帐里。","败许尘疏中。"]},{"t":"读曲歌八十九首 其八十四","f":"五言绝句","c":["紫草生湖边，误落芙蓉里。","色分都未获，空中染莲子。"]},{"t":"读曲歌八十九首 其八十五","f":"五言绝句","c":["闺閤断信使，的的两相忆。","譬如水上影，分明不可得。"]},{"t":"读曲歌八十九首 其八十六","f":"五言绝句","c":["逍遥待晓分，转侧听更鼓。","明月不应停，特为相思苦。"]},{"t":"读曲歌八十九首 其八十七","f":"五言绝句","c":["罢去四五年，相见论故情。","杀荷不断藕，莲心已复生。"]},{"t":"读曲歌八十九首 其八十八","f":"五言绝句","c":["辛苦一朝欢，须臾情易厌。","行膝点芙蓉，深莲非骨念。"]},{"t":"读曲歌八十九首 其八十九","f":"五言绝句","c":["慊苦忆侬欢，书作后非是。","五果林中度，见花多忆子。"]},{"t":"石城乐 其二","f":"五言绝句","c":["阳春百花生，摘插环髻前。","捥指蹋忘愁，相与及盛年。"]},{"t":"石城乐 其三","f":"五言绝句","c":["布帆百馀幅，环环在江津。","执手双泪落，何时见欢还。"]},{"t":"石城乐 其四","f":"五言绝句","c":["大艑载三千，渐水丈五馀。","水高不得渡，与欢合生居。"]},{"t":"莫愁乐 其一","f":"五言绝句","c":["莫愁在何处，莫愁石城西。","艇子打两桨，催送莫愁来。"]},{"t":"莫愁乐 其二","f":"五言绝句","c":["闻欢下扬州，相送楚山头。","探手抱腰看，江水断不流。"]},{"t":"乌夜啼 其三","f":"五言绝句","c":["辞家远行去，侬欢独离居。","此日无啼音，裂帛作还书。"]},{"t":"乌夜啼 其四","f":"五言绝句","c":["可怜乌臼鸟，强言知天曙。","无故三更啼，欢子冒暗去。"]},{"t":"乌夜啼 其五","f":"五言绝句","c":["乌生如欲飞，飞飞各自去。","生离无安心，夜啼至天曙。"]},{"t":"乌夜啼 其六","f":"五言绝句","c":["笼窗窗不开，荡户户不动。","欢下葳蕤龠，交侬那得往。"]},{"t":"乌夜啼 其七","f":"五言绝句","c":["远望千里烟，隐当在欢家。","欲飞无两翅，当奈独思何。"]},{"t":"乌夜啼 其八","f":"五言绝句","c":["巴陵三江口，芦荻齐如麻。","执手与欢别，痛切当奈何。"]},{"t":"襄阳乐 其二","f":"五言绝句","c":["上水郎担篙，下水摇双橹。","四角龙子幡，环环江当柱。"]},{"t":"襄阳乐 其三","f":"五言绝句","c":["江陵三千三，西塞陌中央。","但问相随否，何计道里长。"]},{"t":"襄阳乐 其四","f":"五言绝句","c":["人言襄阳乐，乐作非侬处。","乘星冒风流，还侬扬州去。"]},{"t":"襄阳乐 其五","f":"五言绝句","c":["烂漫女萝草，结曲绕长松。","三春虽同色，岁寒非处侬。"]},{"t":"襄阳乐 其六","f":"五言绝句","c":["扬州蒲锻环，百钱两三丛。","不能买将还，空手揽抱侬。"]},{"t":"襄阳乐 其八","f":"五言绝句","c":["恶见多情欢，罢侬不相语。","莫作乌集林，忽如提侬去。"]},{"t":"寿阳乐 其一","f":"古风","c":["可怜八公山。","在寿阳。","别后莫相忘。"]},{"t":"寿阳乐 其二","f":"古风","c":["东台百馀尺。","凌风云。","别后不忘君。"]},{"t":"寿阳乐 其三","f":"古风","c":["梁长曲水流。","明如镜。","双林与郎照。"]},{"t":"寿阳乐 其四","f":"古风","c":["辞家远行去。","空为君。","明知岁月驶。"]},{"t":"寿阳乐 其五","f":"古风","c":["笼窗取凉风。","弹素琴。","一叹复一吟。"]},{"t":"寿阳乐 其六","f":"古风","c":["夜相思。","望不来。","人乐我独愁。"]},{"t":"寿阳乐 其七","f":"古风","c":["长淮何烂漫。","路悠悠。","得当乐忘忧。"]},{"t":"寿阳乐 其八","f":"古风","c":["上我长濑桥。","望归路。","秋风停欲度。"]},{"t":"寿阳乐 其九","f":"古风","c":["衔泪出伤门。","寿阳去。","必还当几载。"]},{"t":"西乌夜飞 其二","f":"五言绝句","c":["暂请半日给，徙倚娘店前。","目作宴瑱饱，腹作宛恼饥。"]},{"t":"西乌夜飞 其三","f":"五言绝句","c":["我昨忆欢时，揽刀持自刺。","自刺分应死，刀作杂楼僻。"]},{"t":"西乌夜飞 其五","f":"五言绝句","c":["感郎崎岖情，不复自顾虑。","臂绳双入结，遂成同心去。"]},{"t":"宋宗庙登歌八首 其一 北平府君歌","f":"古风","c":["绵绵遐绪，明昭载融。","汉德未远，尧有遗风。","于穆皇祖，永世克隆。","本支惟庆，贻厥靡穷。"]},{"t":"宋宗庙登歌八首 其二 相国掾府君歌","f":"古风","c":["乃立清庙，清庙肃肃。","乃备礼容，礼容穆穆。","显允皇祖，昭是嗣服。","锡兹繁祉，聿怀多福。"]},{"t":"宋宗庙登歌八首 其三 开封府君歌","f":"古风","c":["四县既序，箫管既举。","堂献六瑚，庭万八羽。","先王有典，克禋皇祖。","不显洪烈，永介休祜。"]},{"t":"宋宗庙登歌八首 其四 武原府君歌","f":"古风","c":["钟鼓喤喤，威仪将将。","温恭礼乐，致享曾皇。","迈德垂仁，系轨重光。","天命纯嘏，惠我无疆。"]},{"t":"宋宗庙登歌八首 其五 东安府君歌","f":"古风","c":["铄矣皇祖，帝度其心。","永言配命，播兹徽音。","思我茂猷，如玉如金。","骏奔在陛，是鉴是歆。"]},{"t":"宋宗庙登歌八首 其六 孝皇帝歌","f":"古风","c":["烝哉孝皇，齐圣广渊。","发祥诞庆，景祚自天。","德敷金石，道被管弦。","有命既集，徽风永宣。"]},{"t":"宋宗庙登歌八首 其七 高祖武皇帝歌","f":"古风","c":["惟天有命，眷求上哲。","赫矣圣武，抚运桓扰。","功并敷土，道均汝坟。","止戈曰武，经纬称文。","鸟龙失纪，云火代名。","受终改物，作我宋京。","至道惟王，大业有劭。","降德兆民，升歌清庙。"]},{"t":"宋宗庙登歌八首 其八 七庙享神歌","f":"古风","c":["奕奕寝庙，奉璋在庭。","笙龠既列，牺象既盈。","黍稷匪芳，明祀惟馨。","乐具礼充，洁羞荐诚。","神之格思，介以休祯。","济济群辟，永观厥成。"]},{"t":"宋泰始歌舞曲十二首 其二 圣祖颂","f":"五言古诗","c":["圣祖惟高德，积勋代晋历。","永建享鸿基，万古盛音册。","睿文缵宸驭，广运崇帝声。","衍德被仁祉，留化洽民灵。","孝建缔孝业，允协天人谋。","宇内齐政轨，宙表烛威流。","钟管腾列圣，彝铭贲重猷。"]},{"t":"宋泰始歌舞曲十二首 其三 明君大雅","f":"五言古诗","c":["明君应乾数，扰乱绍颓基。","民庆来苏日，国颂薰风诗。","天步或暂艰，列蕃扇迷慝。","庙胜敷九代，神谟洞七德。","文教洗昏俗，武谊清祲埏。","英勋冠帝则，万寿永齐天。"]},{"t":"宋泰始歌舞曲十二首 其五 天符颂","f":"古风","c":["天符革运，世诞英皇。","在馆神炫，既壮龙骧。","六钟集表，四纬骈光。","于穆配天，永休厥祥。"]},{"t":"宋泰始歌舞曲十二首 其六 明德颂","f":"古风","c":["明德孚教，幽苻丽纪。","山鼎见奇，醴液涵祉。","鹓雏耀仪，驺虞游趾。","福延亿祚，庆流万祀。"]},{"t":"宋泰始歌舞曲十二首 其七 帝图颂","f":"古风","c":["帝图凝远，瑞美昭宣。","济流月镜，鹿毳霜鲜。","甘露降和，花雪表年。","孝德载衍，芳风永传。"]},{"t":"宋泰始歌舞曲十二首 其八 龙跃大雅","f":"古风","c":["龙跃戎府，玉耀蕃宫。","岁淹豫野，玺属嫔中。","江波澈映，石柏开文。","观毓花蕊，楼凝景云。","白乌三获，甘液再呈。","嘉穟表沃，连理协成。","德充动物，道积通神。","宋业允大，灵瑞方臻。"]},{"t":"宋泰始歌舞曲十二首 其九 淮祥风","f":"古风","c":["淮祥应。","贤彦生。","翼赞中兴致太平。"]},{"t":"宋泰始歌舞曲十二首 其十 宋世大雅","f":"古风","c":["宋世宁，在泰始。","醉酒欢，饱德喜。","万国朝，上寿酒。","帝同天，惟长久。"]},{"t":"宋泰始歌舞曲十二首 其十二 白纻篇大雅","f":"七言古诗","c":["在心曰志发言诗，声成于文被管丝。","手舞足蹈欣泰时，移风易俗王化基。","琴角挥韵白云舒，箫韶协音神凤来。","拊击和节咏在初，章曲乍毕情有馀。","文同轨一道德行，国靖民和礼乐成。","四县庭响美勋英，八列陛唱贵人声。","舞饰丽华乐容工，罗裳映日袂随风。","金翠列辉蕙麝丰，淑姿秀体允帝衷。"]},{"t":"宋凤凰衔书伎辞","f":"七言古诗","c":["大宋兴隆膺灵符。","凤鸟感和衔素书。","嘉乐之美通玄虚。","惟新济济迈唐虞。","巍巍荡荡道有馀。"]},{"t":"青溪小姑歌二首 其一","f":"古风","c":["日暮风吹，叶落依枝。","丹心寸意，愁君未知。"]},{"t":"青溪小姑歌二首 其二","f":"五言绝句","c":["歌阕夜已久，繁霜侵晓幕。","何意空相守，坐待繁霜落。"]},{"t":"郭长生吹笛歌","f":"五言绝句","c":["闲夜寂已清，长笛亮且鸣。","若欲知我者，姓郭名长生。"]},{"t":"聂包鬼歌","f":"古风","c":["花盈盈。","正间行。","当归不闻死复生。"]},{"t":"陵欣歌","f":"五言绝句","c":["生时世上人，死作狱中鬼。","不得还坟墓，灰没有馀罪。"]},{"t":"鬼谣歌","f":"五言绝句","c":["死树今更青，吴平寻当归。","适闻杀此树，已复有光辉。"]},{"t":"鬼歌","f":"五言绝句","c":["坐侬孔雀楼，遥闻凤凰鼓。","下我邹头山，仿佛见梁鲁。"]},{"t":"犬妖歌","f":"五言绝句","c":["言我不能歌，听我歌梅花。","今年故复可，柰汝明年何。"]},{"t":"鹤吟","f":"五言绝句","c":["畴昔聆好音，日月心延伫。","如何遇良人，中怀邈无绪。"]},{"t":"永明初歌","f":"五言古诗","c":["白马向城啼，欲得城边草。"]},{"t":"百姓为东昏侯歌","f":"古风","c":["阅武堂。","种杨柳。","至尊屠肉。","藩妃酤酒。"]},{"t":"沈麟士引童谣","f":"古风","c":["金鹅鸣。","沈氏兴。","代代出公卿。"]},{"t":"张敬儿自为歌谣","f":"五言绝句","c":["天子在何处，宅在赤谷口。","天子是阿谁，非猪如是狗。"]},{"t":"永明中虏中童谣","f":"古风","c":["黑水流北。","赤火入齐。"]},{"t":"永明中魏地童谣","f":"七言古诗","c":["赤火南流丧南国。"]},{"t":"永元元年童谣","f":"五言古诗","c":["洋洋千里流，流翣东城头。","乌马乌皮裤，三更相告诉。","脚跛不得起，误杀老姥子。"]},{"t":"永元中童谣","f":"五言古诗","c":["野猪虽嗃嗃，马子空闾渠。","不知龙与虎，饮食江南墟。","七九六十三，广莫人无馀。","乌集传舍头，今汝得宽休。","但看三八后，摧折景阳楼。"]},{"t":"山阴谣","f":"古风","c":["二傅沈刘。","不如一丘。"]},{"t":"东昏侯时宫中谣","f":"古风","c":["赵鬼食鸭肃刂。","诸鬼尽著调。"]},{"t":"时人为桓康语","f":"古风","c":["欲侜张。","问桓康。"]},{"t":"荀伯玉闻青衣小儿语","f":"古风","c":["草中肃。","九五相追逐。"]},{"t":"时人为荀伯玉语","f":"古风","c":["十敕五令。","不如荀伯玉命。"]},{"t":"时人为萧晃语","f":"五言古诗","c":["焕焕萧四伞。"]},{"t":"时人为刘绘语","f":"古风","c":["刘绘贴宅，别开一门。"]},{"t":"时人为张周刘三姓语","f":"七言古诗","c":["三人共宅夹清漳。","张南周北刘中央。"]},{"t":"时人为沈麟士语","f":"七言古诗","c":["吴差山中有贤士。","开门教授居成市。"]},{"t":"南州为江革语","f":"五言绝句","c":["故人不道智，新人佞散骑。","莫知度不度，新人不如故。"]},{"t":"都下民语","f":"七言古诗","c":["欲求贵职依刀敕。","须得富豪事御力。"]},{"t":"共戏乐 其一","f":"七言古诗","c":["齐世方昌书轨同。","万宇献乐列国风。"]},{"t":"共戏乐 其二","f":"七言古诗","c":["时泰民康人物盛。","腰鼓铃柈各相竞。"]},{"t":"共戏乐 其三","f":"七言古诗","c":["长袖翩翩若鸿惊。","纤腰袅袅会人情。"]},{"t":"共戏乐 其四","f":"七言古诗","c":["观风采乐德化昌。","圣皇万寿乐未央。"]},{"t":"杨叛儿 其一","f":"五言绝句","c":["截玉作手钩，七宝光平天。","绣沓织成带，严帐信可怜。"]},{"t":"杨叛儿 其三","f":"五言绝句","c":["送郎乘艇子，不作遭风虑。","横篙掷去桨，愿倒逐流去。"]},{"t":"杨叛儿 其四","f":"五言绝句","c":["七宝珠络鼓，教郎拍复拍。","黄牛细犊儿，杨柳映松柏。"]},{"t":"杨叛儿 其五","f":"五言绝句","c":["欢欲见莲时，移湖安屋里。","芙蓉绕床生，眠卧抱莲子。"]},{"t":"杨叛儿 其六","f":"五言古诗","c":["闻欢远行去。","送欢至新亭。","津逻无侬名。"]},{"t":"杨叛儿 其七","f":"五言绝句","c":["落秦中庭生，诚知非好草。","龙头相钩连，见枝如欲绕。"]},{"t":"杨叛儿 其八","f":"五言绝句","c":["杨叛西随曲，柳花经东阴。","风流随远近，飘扬闷侬心。"]},{"t":"乐辞","f":"古风","c":["绣幕围香风。","耳节朱丝桐。","不知理何事。","浅立经营中。","爱惜加穷裤。","防闲托守宫。","今日牛羊上丘陇。","当年近前面发红。"]},{"t":"齐南郊光章十三首 其一 肃咸乐谢超宗","f":"古风","c":["夤承宝命，严恭帝绪。","奄受敷锡，升中拓宇。","亘地称皇，罄天作主。","月域来宾，日际奉土。","开元首正，礼交乐举。","六典联事，九官列序。"]},{"t":"齐南郊光章十三首 其二 引牲乐","f":"古风","c":["皇乎敬矣，恭事上灵。","昭教国祀，肃肃明明。","有牲有涤，有洁在俎。","以荐王衷，以答神祜。","陟配在京，降德在民。","奔精望夜，高燎伫晨。"]},{"t":"齐南郊光章十三首 其三 嘉荐乐","f":"古风","c":["我恭我享，惟孟之春。","以孝以敬，立我烝民。","青坛奄霭，翠幕端凝。","嘉俎重荐，兼籍再升。","设业设虡，展容玉庭。","肇禋配祀，克对上灵。"]},{"t":"齐南郊光章十三首 其四 昭夏乐","f":"古风","c":["惟圣飨帝，惟孝飨亲。","礼行宗祀，敬达郊禋。","金枝中树，广乐四陈。","月御案节，星驱扶轮。","遥光远驾，曜曜振振。","告成大报，受厘元神。"]},{"t":"齐南郊光章十三首 其五 永至乐","f":"古风","c":["紫坛望灵，翠幕伫神。","率天奉贽，罄地来宾。","神贶并介，泯祗合祉。","恭昭鉴享，肃光孝祀。","威蔼四灵，洞曜三光。","皇德全被，大礼流昌。"]},{"t":"齐南郊光章十三首 其六 登歌","f":"古风","c":["报惟事天，祭实尊灵。","史正嘉兆，神宅崇祯。","五畤昭鬯，六宗彝序。","介丘望尘，皇轩肃举。"]},{"t":"齐南郊光章十三首 其八 武德宣烈乐","f":"古风","c":["功烛上宙，德耀中天。","风移九域，礼饰八埏。","四灵晨炳，五纬宵明。","膺历缔运，道茂前声。"]},{"t":"齐南郊光章十三首 其九 高德宣烈乐王俭","f":"古风","c":["飨帝严亲，则天光大。","舄奕前古，荣镜无外。","日月宣华，卿云流霭。","五汉同休，六幽咸泰。"]},{"t":"齐南郊光章十三首 其十 嘉胙乐谢超宗","f":"古风","c":["鬯嘉礼。","承休锡。","盛德符景纬。","昌华应帝策。","圣蔼耀昌基。","融祉晖世历。","声正涵月轨。","书文同日迹。","宝瑞昭神图。","灵贶流瑞液。","我皇崇晖祚。","重芬冠往籍。"]},{"t":"齐南郊光章十三首 其十一 昭夏乐","f":"古风","c":["荐飨洽，礼乐该。","神娱展，辰旆回。","洞云路，拂璇阶。","紫雰蔼，青霄开。","眷皇都，顾玉台。","留昌德，结圣怀。"]},{"t":"齐南郊光章十三首 其十二 昭远乐","f":"古风","c":["天以德降，地以礼报。","牲尊俯陈，柴币仰燎。","事展司采，敬达瑄芗。","烟贽青昊，震飏紫场。","陈馨示策，肃志宗禋。","礼非物备，福唯诚陈。"]},{"t":"齐南郊光章十三首 其十三 休成乐","f":"古风","c":["昭事上祀，飨荐具陈。","回銮转翠，拂景翔宸。","缀县敷畅，钟石昭融。","羽炫深晷，龠曀行风。","肆序辍度，肃礼停文。","四金耸卫，六驭齐轮。"]},{"t":"齐北郊乐歌六首 其一 昭夏乐谢超宗","f":"古风","c":["诏礼崇营，敬飨玄畤。","灵正丹帷，月肃紫墀。","展荐登华，风县凝锵。","神惟戾止，郁葆遥庄。","昭望岁芬，环游辰太。","穆哉尚礼，横光秉蔼。"]},{"t":"齐北郊乐歌六首 其二 登歌","f":"古风","c":["伫灵敬享，禋肃彝文。","县动声仪，荐絜牲芬。","阴祇以贶，昭祀式庆。","九服熙度，六农祥正。"]},{"t":"齐北郊乐歌六首 其三 地德凯容乐","f":"古风","c":["缮方丘，端国阴。","掩圭晷，仰灵心。","诏源委，遍丘林。","礼献物，乐荐音。"]},{"t":"齐北郊乐歌六首 其四 昭德凯容乐","f":"古风","c":["庆图浚邈，蕴祥秘瑶。","伣天炳月，嫔光紫霄。","邦化灵懋，阃则风调。","俪德方仪，徽载以昭。"]},{"t":"齐北郊乐歌六首 其五 昭夏乐","f":"古风","c":["荐神升，享序楙。","淹玉俎，停金奏。","宝旆转，旒驾旋。","溢素景，郁紫躔。","灵心顾，留宸眷。","洽外瀛，瑞中县。"]},{"t":"齐北郊乐歌六首 其六 隶幽乐","f":"古风","c":["后皇嘉庆，定祗玄畤。","承帝休图，祗敷灵祉。","篚幂周序，轩朱凝会。","牲币芬坛，精明伫盖。","调川瑞昌，警岳祥泰。"]},{"t":"齐明堂乐歌十五首 其一 肃咸乐谢超宗","f":"古风","c":["彝承孝典，恭事严圣。","浃天奉赆，罄壤齐庆。","司仪具序，羽容夙章。","芬枝扬烈，黼构周张。","助宝奠轩，酎珍充庭。","璆县凝会，琄朱伫声。","先期选礼，肃若有承。","祗对灵祉，皇庆昭膺。"]},{"t":"齐明堂乐歌十五首 其二","f":"古风","c":["尊事威仪，辉容昭序。","迅恭明神，絜盛牲俎。","肃肃严宫，蔼蔼崇基。","皇灵降止，百祗具司。","戒诚望夜，端烈承朝。","依微昭旦，物色轻宵。"]},{"t":"齐明堂乐歌十五首 其三 引牲乐","f":"古风","c":["惟诚絜飨，惟孝尊灵。","敬度黍稷，敬涤牺牲。","骍茧在豢，载溢载丰。","以承宗祀，以肃皇衷。","萧芳四举，华火周传。","神鉴孔昭，嘉足三牷。"]},{"t":"齐明堂乐歌十五首 嘉荐乐二首 其四","f":"古风","c":["肇禋戒祀，礼容咸举。","六典饰文，九司照序。","牲柔既昭，牺刚既陈。","恭涤惟清，敬事惟神。","加笾再御，兼俎重荐。","节动轩越，声流金县。"]},{"t":"齐明堂乐歌十五首 其五","f":"古风","c":["奕奕閟幄，亹亹严闱。","絜诚夕鉴，端服晨晖。","圣灵戾止，翊我皇则。","上绥四宇，下洋万国。","永言孝飨，孝飨有容。","傧僚赞列，肃肃雍雍。"]},{"t":"齐明堂乐歌十五首 其六 昭夏乐","f":"古风","c":["地纽谧，乾枢回。","华盖动，紫微开。","旌蔽日，车若云。","驾六龙，乘烟煴。","烨帝景，耀天邑。","圣祖降，五云集。","懋粢盛，絜牲牷。","百礼肃，群司虔。","皇德远，大孝昌。","贯九幽，洞三光。","神之安，解玉銮。","景福至，万宇欢。"]},{"t":"齐明堂乐歌十五首 其七 登歌","f":"古风","c":["雍台辨朔，泽宫选辰。","絜火夕炤，明水朝陈。","六瑚贲室，八羽华庭。","昭事先圣，怀濡上灵。","肆夏式敬，升歌发德。","永固洪基，以绥万国。"]},{"t":"齐明堂乐歌十五首 其八 凯容宣烈乐","f":"古风","c":["酾醴具登，嘉佾咸荐。","飨洽诚陈，礼周乐遍。","祝辞罢裸，序容辍县。","跸动端庭，銮回严殿。","神仪驻景，华汉高虚。","作灵案卫，三只解途。","翠盖澄耀，罼帟凝宸。","玉镳息节，金辂怀音。","戒诚达孝，底心肃感。","追凭皇鉴，思承渊范。","神锡懋祉，四纬昭明。","仰福帝徽，俯齐庶生。"]},{"t":"齐明堂乐歌十五首 其九 青帝歌","f":"古风","c":["参映夕，驷昭晨。","灵乘震，司青春。","雁将向，桐始蕤。","和风舞，暄光迟。","萌动达，万品亲。","润无际，泽无垠。"]},{"t":"齐明堂乐歌十五首 其十 赤帝歌","f":"古风","c":["龙精初见。","大火中。","朱光北至。","圭景同。","帝在在离。","寔司衡。","雨水方降。","木槿荣。","庶物盛长。","咸殷阜。","恩泽四溟。","被九有。"]},{"t":"齐明堂乐歌十五首 其十一 黄帝歌","f":"五言律诗","c":["履艮宅中宇，司绳总四方。","裁化遍寒燠，布政司炎凉。","至分乘经晷，闭启集恒度。","帝晖缉万有，皇灵澄国步。"]},{"t":"齐明堂乐歌十五首 其十二 白帝歌","f":"古风","c":["百川若镜。","天地爽且明。","云冲气举。","盛德在素精。","庶类收成。","岁功行欲宁。","浃地奉渥。","罄宇承帝灵。"]},{"t":"齐明堂乐歌十五首 其十三 黑帝歌","f":"古风","c":["岁既暮日方驰，灵乘坎德司规。","玄云合晦鸟蹊，白灵繁亘天涯。","晨晷促夕漏延，太阴极微阳宣。"]},{"t":"齐明堂乐歌十五首 其十四 嘉胙乐","f":"古风","c":["神荐洽。","福胙昌。","圣皇膺嘉佑。","帝业凝休祥。","居极乘景运。","宅德瑞中王。","澄明临四奥。","精华延八乡。","洞海同声惠。","澈宇丽乾光。","灵庆缠世祉。","鸿烈永无疆。"]},{"t":"齐明堂乐歌十五首 其十五 昭夏乐","f":"古风","c":["蕴礼容。","馀乐度。","灵方留。","景欲暮。","开九重。","肃五达。","凤参差。","龙已沫。","云既动。","河既梁。","万里照。","四空香。","神之车。","归清都。","璇庭寂。","玉殿虚。","鸿化疑。","孝风炽。","顾灵心。","结皇思。","鸿庆遐鬯。","嘉荐令芳。","翊帝明德。","永祚深光。"]},{"t":"齐前后舞歌二首 其一 前舞阶步歌","f":"古风","c":["天挺圣哲，三方维纲。","川岳伊宁，七曜重光。","茂育万物，众庶咸康。","道用潜通，仁施遐扬。","德厚坤极，功高昊苍。","舞象盛容，德以歌章。","八音既节，龙跃凤翔。","皇基永树，二仪等长。"]},{"t":"齐前后舞歌二首 其二 后舞阶步歌","f":"古风","c":["皇皇我后，绍业盛明。","涤拂除秽，宇宙载清。","允执中和，以莅苍生。","玄化远被，兆世轨形。","何以崇德，乃作九成。","妍步恂恂，雅曲芬馨。","八风清鼓，应以祥祯。","泽浩天下，功齐百灵。"]},{"t":"齐鼙舞曲三首 其二 圣主曲辞","f":"五言古诗","c":["圣主受天命，应期则虞唐。","升旒综万机，端扆驭八方。","盈虚自然数，揖让归圣明。","北化陵河塞，南威越沧溟。","广德齐七政，敷教腾三辰。","万宇必承庆，百福咸来臻。","圣皇应福始，昌德洞佑先。"]},{"t":"齐鼙舞曲三首 其三 明君辞","f":"五言古诗","c":["明君御四海，总鉴尽人灵。","仰成恩已洽，竭忠身必荣。","圣泽洞三灵，德教被八乡。","草木变柯叶，川岳洞嘉祥。","愉乐盛明运，舞蹈升太时。","微霜永昌命，轨心长欢怡。"]},{"t":"齐民昌辞","f":"古风","c":["齐世昌。","四海安乐齐太平。","人命长。","当结久。","千秋万岁皆老寿。"]},{"t":"荆州民为始兴王憺歌","f":"古风","c":["始兴王。","民之爹。","赴人急。","如水火。","何时复来哺乳我。"]},{"t":"北军为韦睿歌","f":"七言古诗","c":["不畏萧娘与吕姥。","但畏合肥有韦武。"]},{"t":"鄱阳民为陆襄歌二首 其一","f":"古风","c":["鲜于平后善恶分。","民无枉赖陆君。"]},{"t":"鄱阳民为陆襄歌二首 其二","f":"古风","c":["陆君政，无怨家。","斗既罢，仇共车。"]},{"t":"南豫州民为夏侯兄弟歌","f":"古风","c":["我之有州，赖彼夏侯。","前兄后弟，布政优优。"]},{"t":"梁武帝接民间为萧恪歌","f":"古风","c":["江千万。","蔡五百。","王新车。","庾大宅。","主人愦愦不如客。"]},{"t":"北方童谣","f":"五言绝句","c":["荆山为上格，浮山为下格。","潼沱为激沟，并灌钜野泽。"]},{"t":"洛阳童谣","f":"七言古诗","c":["名军大将莫自牢。","千兵万马避白袍。"]},{"t":"梁武帝时谣","f":"古风","c":["莫匆匆。","且宽公。","谁当作天子。","草覆车边已。"]},{"t":"昭明为太子时谣","f":"五言古诗","c":["鹿子开城门，城门鹿子开。","当开复未开，使我心徘徊。","城中诸少年，逐欢归去来。"]},{"t":"普通中童谣","f":"七言古诗","c":["青丝白马寿阳来。"]},{"t":"侯景时的脰乌童谣","f":"古风","c":["的脰乌。","拂朱雀。","还与吴。"]},{"t":"侯景即位时童谣","f":"古风","c":["脱青袍。","著芒屩。","荆州天子挺应著。"]},{"t":"江陵童谣","f":"古风","c":["苦竹町。","市南有好井。","荆州军。","杀侯景。"]},{"t":"湘东王府中为鱼宏徐绲谣","f":"古风","c":["北路鱼。","南路徐。"]},{"t":"柳达摩引北方童谣","f":"五言古诗","c":["石头捣两裆。","捣青复捣黄。"]},{"t":"梁时童谣","f":"古风","c":["虏万夫。","入五湖。","城南酒家使虏奴。"]},{"t":"梁末童谣","f":"五言古诗","c":["可怜巴马子，一日行千里。","不见马上郎，但有黄尘起。","黄尘污人衣，皂荚相料理。"]},{"t":"百姓为萧正德父子谣","f":"古风","c":["宁逢五虎入市。","不欲见临贺父子。"]},{"t":"鸟山童谣","f":"五言古诗","c":["鸟山出天子。"]},{"t":"三馀童谣","f":"七言古诗","c":["夫子之居在三馀。"]},{"t":"谚语后人引梁世谚论史职","f":"七言古诗","c":["上车不落则著作，体中保如则秘书。"]},{"t":"梁元帝引谚论占雨","f":"古风","c":["雨月额千里赤。"]},{"t":"刘昼引谚","f":"古风","c":["力贵突。","智贵卒。"]},{"t":"刘昼引古谚","f":"五言绝句","c":["深不绝涓泉，稚子浴其渊。","高不绝丘陵，跛羊游其巅。"]},{"t":"任昉引南海俗谚","f":"古风","c":["蛇珠千枚。","不及玫瑰。"]},{"t":"任昉引越人谚","f":"五言古诗","c":["种千亩木奴。","不如一龙珠。"]},{"t":"颜之推引江南谚论书法","f":"古风","c":["尺牍书疏，千里面目。"]},{"t":"时人为张氏语","f":"古风","c":["充融卷稷，是为四张。"]},{"t":"时人为王谢子弟语","f":"古风","c":["谢有览举。","王有养炬。"]},{"t":"时人为张融陆杲语","f":"古风","c":["无对日下，惟舅与甥。"]},{"t":"时人为何子朗语 其一","f":"古风","c":["东海三何。","子朗最多。"]},{"t":"时人为何子朗语 其二","f":"七言古诗","c":["人中爽爽何子朗。"]},{"t":"时人为王志王彬语","f":"古风","c":["三真六草。","为天下宝。"]},{"t":"时人为鲍正语","f":"古风","c":["无处不逢鸟噪，无处不逢鲍佐。"]},{"t":"巴东行人为庾子舆语","f":"七言古诗","c":["淫预如幞本不通。","瞿塘水退为庾公。"]},{"t":"时人为玉莹语","f":"古风","c":["欲向南，钱可贪。","遂向东，为黄铜。"]},{"t":"省中为贺琛语","f":"七言古诗","c":["上殿不下有贺雅。"]},{"t":"时人为丁觇语","f":"古风","c":["丁君十纸。","不敌王褒数字。"]},{"t":"都下为禅师语","f":"五言古诗","c":["斗场禅师窟，安东谈议林。"]},{"t":"任昉引古诗论魏武陵","f":"五言古诗","c":["石犬不可吠。","铜驼徒尔为。"]},{"t":"任昉引古诗论香泉","f":"五言古诗","c":["安得香水泉，濯朗衣上尘。"]},{"t":"陌上桑","f":"五言绝句","c":["日出秦楼明，条垂露尚盈。","蚕饥心自急，开奁妆不成。"]},{"t":"攀杨枝","f":"五言绝句","c":["自从别君来，不复著绫罗。","画眉不注口，施朱当柰何。"]},{"t":"乐府诗","f":"古风","c":["梧宫秋。","吴王愁。"]},{"t":"企喻歌 其二","f":"古风","c":["放马大泽中，草好马著膘。","牌子铁裲裆，?矛鸐尾条。"]},{"t":"企喻歌 其三","f":"古风","c":["前行看后行，齐著铁裲裆。","前头看后头，齐著铁?矛。"]},{"t":"琅琊王歌辞 其二","f":"五言绝句","c":["琅琊复琅琊，琅琊大道王。","阳春二三月，单衫绣裲裆。"]},{"t":"琅琊王歌辞 其三","f":"五言绝句","c":["东山看西水，水流盘石间。","公死姥更嫁，孤儿甚可怜。"]},{"t":"琅琊王歌辞 其四","f":"五言绝句","c":["琅琊复琅琊，琅琊大道王。","鹿鸣思长章，愁人思故乡。"]},{"t":"琅琊王歌辞 其五","f":"五言绝句","c":["长安十二门，光门最妍雅。","渭水从垄来，浮游渭桥下。"]},{"t":"琅琊王歌辞 其六","f":"五言绝句","c":["琅琊复琅琊，女郎大道王。","孟阳三四月，移铺逐阴凉。"]},{"t":"琅琊王歌辞 其七","f":"五言绝句","c":["客行依主人，愿得主人强。","猛虎依深山，愿得松柏长。"]},{"t":"琅琊王歌辞 其八","f":"五言绝句","c":["懀马高缠鬃，遥知身是龙。","谁能骑此马，唯有广平公。"]},{"t":"钜鹿公主歌辞 其一","f":"七言古诗","c":["官家出游雷大鼓。","细乘犊车开后户。"]},{"t":"钜鹿公主歌辞 其二","f":"七言古诗","c":["车前女子年十五。","手弹琵琶玉节舞。"]},{"t":"钜鹿公主歌辞 其三","f":"七言古诗","c":["钜鹿公主殷照女。","皇帝陛下万几主。"]},{"t":"紫骝马歌辞 其一","f":"五言绝句","c":["烧火烧野田，野鸭飞上天。","童男娶寡妇，壮女笑杀人。"]},{"t":"紫骝马歌辞 其二","f":"五言绝句","c":["高高山头树，风吹叶落去。","一去数千里，何当还故处。"]},{"t":"紫骝马歌辞 其四","f":"五言绝句","c":["遥看是君家，松柏冢累累。","兔从狗窦入，雉从梁上飞。"]},{"t":"紫骝马歌辞 其五","f":"五言绝句","c":["中庭生旅谷，井上生旅葵。","舂谷持作饭，采葵持作羹。"]},{"t":"紫骝马歌辞 其六","f":"五言绝句","c":["羹饭一时熟，不知饴阿谁。","出门东向望，泪落沾我衣。"]},{"t":"紫骝马歌","f":"五言绝句","c":["独柯不成树，独树不成林。","念郎锦裲裆，恒长不忘心。"]},{"t":"黄淡思歌 其一","f":"五言绝句","c":["归归黄淡思，逐郎还去来。","归归黄淡百，逐郎何处索。"]},{"t":"黄淡思歌 其二","f":"五言绝句","c":["心中不能言，腹作车轮旋。","与郎相知时，但恐傍人闻。"]},{"t":"黄淡思歌 其三","f":"五言绝句","c":["江外何郁拂，龙洲广州出。","象牙作帆樯，绿丝作帏繂。"]},{"t":"黄淡思歌 其四","f":"五言古诗","c":["绿丝何葳蕤。","逐郎归去来。"]},{"t":"地驱乐歌 其一","f":"古风","c":["青青黄黄，雀石颓唐。","槌杀野牛，押杀野羊。"]},{"t":"地驱乐歌 其二","f":"古风","c":["驱羊入谷，自羊在前。","老女不嫁，蹋地唤天。"]},{"t":"地驱乐歌 其三","f":"古风","c":["侧侧力力，念君无极。","枕郎左臂，随郎转侧。"]},{"t":"地驱乐歌 其四","f":"古风","c":["摩将郎须，看郎颜色。","郎不念女，不可与力。"]},{"t":"地驱乐歌","f":"七言古诗","c":["月明光光星欲堕。","欲来不来早语我。"]},{"t":"雀劳利歌辞","f":"古风","c":["雨雪霏霏雀劳利。","长觜饱满觜饥。"]},{"t":"慕容垂歌辞三曲 其一","f":"五言绝句","c":["慕容攀墙视，吴军无边岸。","我身分自当，枉杀墙外汉。"]},{"t":"慕容垂歌辞三曲 其二","f":"五言绝句","c":["慕容愁愤愤，烧香作佛会。","愿作墙里燕，高飞出墙外。"]},{"t":"慕容垂歌辞三曲 其三","f":"五言绝句","c":["慕容出墙望，吴军无边岸。","咄我臣诸佐，此事可惋叹。"]},{"t":"陇头流水歌 其二","f":"古风","c":["西上陇阪，羊肠九回。","山高谷深，不觉脚酸。"]},{"t":"陇头流水歌 其三","f":"古风","c":["手攀弱枝。","足逾弱泥。"]},{"t":"陇头歌辞 其一","f":"古风","c":["陇头流水，流离山下。","念吾一身，飘然旷野。"]},{"t":"陇头歌辞 其二","f":"古风","c":["朝发欣城，暮宿陇头。","寒不能语，舌卷入喉。"]},{"t":"陇头歌辞 其三","f":"古风","c":["陇头流水，鸣声幽咽。","遥望秦川，心肠断绝。"]},{"t":"隔谷歌 其一","f":"古风","c":["兄在城中弟在外。","弓无弦。","箭无栝。","食粮乏尽若为活。","救我来。","救我来。"]},{"t":"隔谷歌 其二","f":"七言绝句","c":["兄为俘虏受困辱。","骨露力疲食不足。","弟为官吏马食粟。","何惜钱刀来我赎。"]},{"t":"淳于王歌 其一","f":"五言绝句","c":["肃肃河中育，育熟须含黄。","独坐空房中，思我百媚郎。"]},{"t":"淳于王歌 其二","f":"五言绝句","c":["百媚在城中，千媚在中央。","但使心相念，高城何所妨。"]},{"t":"东平刘生歌","f":"古风","c":["东平刘生安东子。","树木稀。","屋里无人看阿谁。"]},{"t":"捉搦歌 其一","f":"七言绝句","c":["粟谷难舂付石臼。","弊衣难护付巧妇。","男儿千凶饱人手。","老女不嫁只生口。"]},{"t":"捉搦歌 其二","f":"七言绝句","c":["谁家女子能行步。","反著夹禅后裙露。","天生男女共一处。","愿得两个成翁妪。"]},{"t":"捉搦歌 其三","f":"七言绝句","c":["华阴山头百丈井。","下有流水彻骨冷。","可怜女子能照影。","不见其馀见斜领。"]},{"t":"捉搦歌 其四","f":"七言绝句","c":["黄桑柘屐蒲子履。","中央有丝两头系。","小时怜母大怜婿。","何不早嫁论家计。"]},{"t":"折杨柳歌辞 其一","f":"五言绝句","c":["上马不捉鞭，反折杨柳枝。","蹀座吹长笛，愁杀行客儿。"]},{"t":"折杨柳歌辞 其二","f":"五言绝句","c":["腹中愁不乐，愿作郎马鞭。","出入擐郎臂，蹀座郎膝边。"]},{"t":"折杨柳歌辞 其三","f":"五言绝句","c":["放马两泉泽，忘不著连羁。","担鞍逐马走，何见得马骑。"]},{"t":"折杨柳枝歌","f":"五言绝句","c":["门前一株枣，岁岁不知老。","阿婆不嫁女，那得孙儿抱。"]},{"t":"幽州马客吟歌辞 其二","f":"五言绝句","c":["荧荧帐中烛，烛灭不久停。","盛时不作乐，春花不重生。"]},{"t":"幽州马客吟歌辞 其三","f":"五言绝句","c":["南山自言高，只与北山齐。","女儿自言好，故入郎君怀。"]},{"t":"幽州马客吟歌辞 其四","f":"五言绝句","c":["郎著紫裤褶，女著彩夹裙。","男女共燕游，黄花生后园。"]},{"t":"幽州马客吟歌辞 其五","f":"五言绝句","c":["黄花郁金色，绿蛇衔珠丹。","辞谢床上女，还我十指环。"]},{"t":"慕容家自鲁企由谷歌","f":"五言绝句","c":["郎在十重楼，女在九重阁。","郎非黄鹞子，那得云中雀。"]},{"t":"高阳乐人歌 其一","f":"五言绝句","c":["可怜白鼻騧，相将入酒家。","无钱但共饮，画地作交赊。"]},{"t":"高阳乐人歌 其二","f":"五言绝句","c":["何处䑜觞来，两颊色如火。","自有桃花容，莫言人劝我。"]},{"t":"咸阳宫人为咸阳王禧歌","f":"古风","c":["可怜咸阳王。","奈何作事误。","金床玉几不能眠。","夜踏霜与露。","洛水湛湛弥岸长。","行人那得渡。"]},{"t":"河北民为裴侠歌","f":"古风","c":["肥鲜不食，丁庸不取。","裴公贞惠，为世规矩。"]},{"t":"时人为上高里歌","f":"七言绝句","c":["洛阳城北上高里。","殷之顽民昔所止。","今日百姓造瓮子。","人皆弃去住者耻。"]},{"t":"湘川渔者歌","f":"古风","c":["帆随湘转。","望衡九面。"]},{"t":"赵郡为李曾谣","f":"五言古诗","c":["诈作赵郡鹿。","犹胜常山粟。"]},{"t":"河东民为元淑谣","f":"古风","c":["泰州河东，杼柚代舂。","元公至止，田畴始理。"]},{"t":"宣武孝明时谣","f":"古风","c":["狐非狐。","貉非貉。","焦梨狗子齿断索。"]},{"t":"孝明时洛下谣","f":"五言古诗","c":["铜拔打铁拔。","元家世将末。"]},{"t":"清河民为宋世良谣 其一","f":"古风","c":["宁度东吴会稽。","不历成公曲堤。"]},{"t":"清河民为宋世良谣 其二","f":"七言古诗","c":["曲堤虽险贼何益。","但有宋公自屏迹。"]},{"t":"洛中童谣二首 其一","f":"古风","c":["三月末。","四月初。","杨灰簸土觅真珠。"]},{"t":"洛中童谣二首 其二","f":"古风","c":["头去项，脚根齐。","驱上树，不须梯。"]},{"t":"西魏时童谣","f":"古风","c":["獾獾头团圞。","河中狗子破尔苑。"]},{"t":"东魏童谣","f":"五言绝句","c":["可怜青雀子，飞来邺城里。","羽翮垂欲成，化作鹦鹉子。"]},{"t":"东魏武定末童谣","f":"古风","c":["百尺高竿摧折。","水底燃灯灯灭。"]},{"t":"祖珽引魏世谣","f":"七言古诗","c":["河南种谷河北生。","白杨树头金鸡鸣。"]},{"t":"柳楷引谣","f":"七言古诗","c":["鸾生十子九子瑖。","一子不瑖关中乱。"]},{"t":"诘汾力微谚","f":"七言古诗","c":["诘汾皇帝无妇家。","力微皇帝无舅家。"]},{"t":"时人为李崇元融语","f":"古风","c":["陈留章武，伤腰折股。","贪人败类，秽我明主。"]},{"t":"时人为安丰中山济南三王语","f":"七言古诗","c":["三王楚楚尽琳琅。","未若济南备圆方。"]},{"t":"时人为祖莹袁翻语","f":"古风","c":["京师楚楚。","袁与祖。","洛阳翩翩。","祖与袁。"]},{"t":"同门生为李谧语","f":"古风","c":["青成蓝，蓝谢青。","师何常，在明经。"]},{"t":"时人为元颐元钦语","f":"古风","c":["皇宗略略。","寿安思若。"]},{"t":"时人为王嶷语","f":"古风","c":["实痴实昏。","终得保存。"]},{"t":"百姓为公孙轨语","f":"古风","c":["驴无强弱，辅脊自壮。"]},{"t":"时人为王遵业王延明语","f":"古风","c":["英英济济。","王家兄弟。"]},{"t":"桑乾乡里为房景伯语","f":"古风","c":["有义有礼。","房家兄弟。"]},{"t":"时人为崔楷语","f":"古风","c":["莫?獬。","付崔楷。"]},{"t":"李彪引谚","f":"古风","c":["一日不书。","百事荒芜。"]},{"t":"邢峦引俗谚","f":"五言古诗","c":["耕则问田奴，绢则问织婢。"]},{"t":"高谦之引谚","f":"古风","c":["迷而知反。","得道未还。"]},{"t":"贼为杨津语","f":"古风","c":["不畏利槊坚城。","惟畏杨公铁星。"]},{"t":"相府为裴汉语","f":"七言古诗","c":["日下粲烂有裴汉。"]},{"t":"杨衒之引语","f":"七言古诗","c":["洛阳男儿急作髻。","瑶光寺尼夺作婿。"]},{"t":"杨衒之引谣语","f":"五言绝句","c":["狱中无系囚，舍内无青州。","假令家道恶，腹中不怀愁。"]},{"t":"杨衒之引京师语","f":"古风","c":["洛鲤伊鲂。","贵于牛羊。"]},{"t":"杨衒之引京师语","f":"古风","c":["白马甜榴。","一实直牛。"]},{"t":"杨衒之引游侠语","f":"古风","c":["不畏张弓拔刀。","唯畏白堕春醪。"]},{"t":"杨衒之引秦民语","f":"古风","c":["快马健儿。","不如老妪吹篪。"]},{"t":"阚骃引语","f":"七言古诗","c":["沛国龙穴至山乘。","诈托旅使若奔丧。","道遇寇抄失资粮。"]},{"t":"郦道元引橘洲谚","f":"七言古诗","c":["昭潭无底橘洲浮。"]},{"t":"郦道元引俗谚论清泉河","f":"五言古诗","c":["高梁无上源，清泉无下尾。"]},{"t":"郦道元引古语论南北岈","f":"古风","c":["南岈北岈。","万有馀家。"]},{"t":"郦道元引涝滩净滩谚","f":"古风","c":["冬涝夏净。","断官使命。"]},{"t":"郦道元引语","f":"五言古诗","c":["绵洛为没沃。"]},{"t":"高允引谚","f":"古风","c":["其益如毫。","其损如刀。"]},{"t":"贾思协引谚论力耕","f":"古风","c":["智如禹汤，不如常耕。"]},{"t":"贾思协引谚论种谷树木","f":"古风","c":["一年之计，莫如种谷。","十年之计，莫如树木。"]},{"t":"贾思协引谚论锄地","f":"五言古诗","c":["锄头三寸泽。"]},{"t":"贾思协引谚论养牛马","f":"古风","c":["羸牛劣马。","寒食下。"]},{"t":"贾思协引河西语","f":"古风","c":["贷我东墙。","偿我田粱。"]},{"t":"仇儒造妖言","f":"古风","c":["燕东倾。","赵当续。","欲知其名。","淮水不足。"]},{"t":"魏孝武帝迁长安时谚","f":"五言古诗","c":["荧惑入南斗。","天子下殿走。"]},{"t":"阿那环","f":"五言绝句","c":["闻有匈奴主，杂骑起尘埃。","列观长平坂，驱马渭桥来。"]},{"t":"杨白花","f":"古风","c":["阳春二三月。","杨柳齐作花。","春风一夜入闺闼。","杨花飘荡落南家。","含情出户脚无力。","拾得杨花泪沾臆。","秋去春还双燕子。","愿衔杨花入窠里。"]},{"t":"化胡歌七首 其一","f":"五言古诗","c":["我往化胡时，头载通天威。","金紫照虚空，燄燄有光晖。","胡王心懭戾，不尊我为师。","吾作变通力，要之出神威。","麾月使东走，须弥而西颓。","足踏乾川桥，日月左右回。","天地昼暗昏，星辰牙差驰。","众灾竞地起，良医绝不知。","胡王心怖怕，叉手向吾啼。","作大慈悲教，化之渐微微。","落簪去一食，右肩不著衣。","男曰忧婆塞，女曰忧婆夷。","化胡今宾服，游神于紫微。"]},{"t":"化胡歌七首 其二","f":"古风","c":["我在舍卫时。","约敕瞿昙身。","汝共摩诃萨。","赍经教东秦。","历落神州界。","迫至东海间。","广宣至尊法。","教授聋俗人。","与子威神法。","化道满千年。","年终时当还。","慎莫恋中秦。","致令天气怒。","太上踏地瞋。","寺庙崩倒澌。","龙王舐经文。","八万四千弟子。","一时受大缘。","轮转五道头。","万元一升仙。","吾子三天上。","悯子泪流连。","念子出行道。","不能却死缘。","不能陵虚空。","束身入黄泉。","天门地户塞。","一去不能还。","虽得存禋嗣。","使子常塞心。","逆天违地理。","灾考加子身。","神能易生死。","由子行不真。","三十六天道。","终卒归无形。","我身西化时。","登上华狱山。","举目看昆仑。","须弥了了悬。","矫翼履清虚。","倏忽到西天。","但见西王母。","严驾欲东旋。","玉女数万千。","姿容甚丽妍。","天姿绝端严。","齐执皇灵书。","诵读仙圣经。","养我同时姝。","将我入天庭。","皇老东向坐。","身体皦然明。","授我仙圣道。","接度天下贤。"]},{"t":"化胡歌七首 其三","f":"五言古诗","c":["我昔西化时。","登上华狱山。","北向视玄冥。","秦川荡然平。","汉少杂类多。","不信至真言。","吾后千馀年。","白骨如丘山。","尸骸路草野。","流血成洪渊。","不忍见子苦。","故作大秦吟。","哀叹二十颂。","以示通中贤。","见机降时世。","不值苦以辛。"]},{"t":"化胡歌七首 其四","f":"五言古诗","c":["我昔化胡时，西登太白山。","修身岩石里，四向集诸仙。","玉女檐浆酪，仙人歌玉文。","天龙翼从后，白虎口驰刚。","玄武负钟鼓，朱雀持幢幡。","化胡成佛道，丈六金刚身。","时与决口教，后当存经文。","吾升九天后，克木作吾身。"]},{"t":"化胡歌七首 其五","f":"五言古诗","c":["我昔离周时，西化向罽宾。","路由函关去，会见尹喜身。","尹喜通窈冥，候天见紫云。","知吾当西过，沐浴齐戒身。","日夜立香火，约敕守门人。","执简迎谒请，延我入皇庭。","叩搏亦无数，求欲从我身。","道取人诚信，三日口不言。","吾知喜心至，遗喜五千文。","欲得求长生，读之易精神。","将喜入西域，迁喜为真人。"]},{"t":"化胡歌七首 其六","f":"古风","c":["我西化胡时。","涉天靡不遥。","牵天覆六合。","艰难身尽婴。","胡人不识法。","放火烧我身。","身亦不缺损。","乃复沉深浏。","龙王折水脉。","复流不复行。","愚人皆哀叹。","枉此贤人身。","吾作腾波气。","起立上著天。","日月头上皦。","光照亿万千。","胡王心方悟。","知是我圣人。","叩头求悔过。","今欲奉侍君。","伏愿降灵气。","怒活国土人。","吾视怨家如赤子。","不顾仇以嫌。","化命一世士。","坐卧诵经文。","身无荣华饰。","后毕得升天。","吾告时世人。","三界里中贤。","欲求长生道。","莫爱千金身。","出身著死地。","返更得生缘。","火中生莲花。","尔乃是至真。","莫有生煞想。","得道升清天。","未负即真信。","丧子千金身。"]},{"t":"化胡歌七首 其七","f":"古风","c":["我昔学道时。","登崖历长松。","盘屈幽谷里。","求觅仙圣公。","食服泥洹散。","渐得不死踪。","九重室中得见不死童。","身体绝华丽。","二仪中无双。","遗我元气乐药。","忽然天圣聪。"]},{"t":"尹喜哀叹五首 其一","f":"五言古诗","c":["尹喜告世人。","欲求长生道。","莫求时世荣。","我昔得道时。","身为关府君。","一日三赏赐。","杂彩以金银。","不以为己有。","施与贫穷人。","白日沾王事。","夜便习灵仙。","餐松食苦柏。","微命乃得存。","精诚神明佑。","守真仰苍天。","感得天地道。","遇见老君身。","难我以父母。","却遗五千文。","秘室熟读之。","三年易精神。","授我仙圣方。","都体解自然。"]},{"t":"尹喜哀叹五首 其二","f":"五言古诗","c":["我昔上九天，下向视玄冥。","但见飞仙士，列翼影清天。","朝宗九天主，太上皇老君。","涤荡六府中，受读仙圣文。","王乔得圣道，游行五岳间。","服气食玉英，受命与天并。"]},{"t":"尹喜哀叹五首 其三","f":"五言古诗","c":["昔往学道时，登岳历高冈。","动见百丈谷，赫赤道里长。","有无极神气，何以到西方。","元以度赤谷，垂泪数千行。","自念宿罪重，五内心摧伤。"]},{"t":"尹喜哀叹五首 其四","f":"五言古诗","c":["我昔求道时，径历数千崖。","浮游八荒外，徒跣身无衣。","东过日出界，西寻清山累。","足底重躎生，手中抱少微。","道见西王母，问我子何归。","耻身不学道，意欲觅仙师。","感我精诚至，乞我鞋以衣。","尔乃得学道，仙气渐微微。","父母怪我晚，昼夜悲嗥啼。","大道与俗返，一往不复归。","高志日日远，不觉心肝摧。","虽得不死道，日月垂微微。","心精不退转，今作天人师。"]},{"t":"尹喜哀叹五首 其五","f":"古风","c":["昔往学道时，踪迹亦难寻。","东到日出界，树木郁郁深。","南到阎浮提，大火烧我身。","西到俱地?，但见金城门。","青龙绕城腹，白虎守城前。","冲天金楼殿，太上居湛然。","光影耀虚空，仙人绝端严。","齐执黄卷书，口诵长生文。","北向入玄冥，大水湛湛深。","绕天数百迎，足底重躎生。","尔乃得仙道，把揽天地神。","子能述吾道，白日得升天。"]},{"t":"太上皇老君哀歌七首 其一","f":"古风","c":["三十六宫主。","太上皇老君。","哀悯下世士。","垂神教世贤。","子欲修冥福。","先当体窈冥。","生时得尊贵。","不如过去荣。","仙驾龙车。","迎子游清天。","上登金楼殿。","坐卧虚空间。","行则飞仙从。","威仪上柱天。","朝登天东头。","暮到于天西。","戏乐九天外。","纵意极周旋。","驱使役百鬼。","总统于万金。"]},{"t":"太上皇老君哀歌七首 其二","f":"五言古诗","c":["吾哀世愚民，不信冥中神。","恃力害良善，不避贤行人。","驰马骋东西，自谓常无前。","善恶毕有报，业缘须臾间。","神明在上见，遣使直往牵。","从上头底收，系著天牢门。","五毒更㸦加，恶神来克侵。","口吟不能言，妻子呼仓天。","莫怨神不佑，由子行不仁。"]},{"t":"太上皇老君哀歌七首 其三","f":"五言古诗","c":["吾哀时世人，不信于神明。","先人与种福，子孙履上行。","衣厚饭得饱，灾考不到门。","口气头嘘天，自谓常终日。","看师真辽然，得病叩头请。","外恭心不敬，神明以知人。","三魂系地狱，七魄悬著天。","三魂消散澌，五神不安宁。","伺命来执宰，丞相踏地瞋。","左神不削死，右神不著生。","生神不卫护，煞神来入身。","或患腰背痛，或患头目疼。","百脉不复流，奋忽入黄泉。","天门地户闭，一去不复还。"]},{"t":"太上皇老君哀歌七首 其四","f":"五言古诗","c":["吾哀世愚人，不信冥中神。","生时不恭敬，死便偿罪缘。","典官逐后驱，牵北走东西。","抱沙填江海，负石累高山。","白日不得食，夜分不得眠。","朝与杖一百，暮与鞭一千。","不堪考对苦，卖罪与生人。","两两共相牵，遂至死灭门。","皆由不敬道，神明考㰅人。","何不敬真神，生死得升天。","生荣死者乐，生死得蒙恩。"]},{"t":"太上皇老君哀歌七首 其五","f":"五言古诗","c":["吾哀时世人，不信冥中神。","一门有十息，纵意行不仁。","神明鉴无外，终不滥煞人。","或夭华秀子，或夭妙少年。","门崩户以坏，学者如浮云。","死亦不脱岁，悲哭仍相寻。","妻子沉堙澌，一身孤独存。","呼天天玄远，呼地地亦深。","不能自怨责，各道怨师尊。","虽欲思善道，十子不复还。"]},{"t":"太上皇老君哀歌七首 其六","f":"五言古诗","c":["吾告时世人，修道宜殷勤。","恩亦不虚生，神明必报人。","昔有刘仲伯，精诚于道门。","勤恶使从善，岁会集群贤。","香火日夜勤，亦能感仓天。","命尽应当死，众神与表天。","三魂飞杨澌，七魄入死星。","右神削死藉，左神著生名。","伺命来极济，左相踏地瞋。","普告二十狱，拔出仲伯身。","三魂还复流，七魄还入身。","血脉还运转，百节方更坚。","面目更端严，肉骨更鲜明。","死臣三七日，寝尸还更生。"]},{"t":"太上皇老君哀歌七首 其七","f":"五言古诗","c":["吾告时世人，髐骨不别真。","闲时不共语，急便来求人。","死者如流水，去者如浮云。","秦川屯军马，中庭生丛榛。","百中不留一，到思吾本言。","何不学仙道，人身常得存。"]},{"t":"老君十六变词 其一","f":"古风","c":["一变之时。","生在南方亦如火。","出胎堕地能独坐。","合口诵经声璅璅。","眼中泪出珠子䂺。","父母世间惊怪我。","复畏寒冻来结果。","身着天衣谁知我。"]},{"t":"老君十六变词 其二","f":"古风","c":["二变之时。","生在西岳在汉川。","寄生王家练精神。","出胎堕地谁语言。","晃晃昱昱似金银。","三十六色绮罗文。","国王欢喜会群臣。","英儒雅士平论。","忽然变化作大人。","发眉皓白头柱天。"]},{"t":"老君十六变词 其三","f":"古风","c":["三变之时。","变形易体在北方。","出胎堕地能居床。","合口诵经声琅琅。","额上三午十二行。","两手不门把文章。","配名天地厚阴阳。","从石入金快翱翔。"]},{"t":"老君十六变词 其四","f":"古风","c":["四变之时。","生在东方身青葱。","出胎堕地能瞳舂。","合口诵经声雍雍。","白日母抱夜乘龙。","昆仑山上或西东。","上天入地登虚空。","仙人侍从数万里。","当此之时神气通。"]},{"t":"老君十六变词 其五","f":"古风","c":["五变之时。","生在中都在洛川。","嵩高少室岭岑颠。","中央修福十万年。","教授仙人数万千。","齐得升天入青云。","降鉴周室八百年。","运终数尽向罽宾。","化胡成佛还东秦。","敷杨道教整天文。"]},{"t":"老君十六变词 其六","f":"古风","c":["六变之时。","生在乾地西北角。","图画天地立五岳。","处置星辰叙四渎。","二十八宿注乡曲。","日月照曜为下国。","走如流水得周局。","智者察之知急速。","雨泽以时熟五䅽。","万人食之大化足。"]},{"t":"老君十六变词 其七","f":"古风","c":["七变之时。","生在北方在海嵎。","出胎堕地声由由。","好喜歌舞无忧愁。","造作音乐作箜篌。","万帝来请用解忧。","黄河为路行竟头。","一身涉世快游游。"]},{"t":"老君十六变词 其八","f":"古风","c":["八变之时。","生在东北在艮地。","图尽天地我次比。","白衣居士维靡诘。","欲结坐禅须谙气。","通畅经书有舍利。","见吾相好须信企。","感子单诚不延次。","齐得升天不堕地。"]},{"t":"老君十六变词 其九","f":"古风","c":["九变之时。","下人黄泉正地柱。","开辟天地施地户。","四气非阳立冥所。","虽有人民不能语。","吾入身中施六府。","胁为傍通心为主。","从此以来能言语。","尊卑大小有次绪。","万天称传道为父。"]},{"t":"老君十六变词 其十","f":"古风","c":["十变之时。","生在东南出风门。","尽出天道安山川。","置立五岳集灵仙。","吹嘘寒暑生万民。","烦气众生人得真。","置立五藏施心神。","动作六神能语言。","有生有死须臾间。","如水东流何时还。","邂逅相代不得停。","何不习善求长生。","槃散流俗入胶盆。","不能免离丧子身。","欲求度世于中禅。","搦心不坚固仙根。","音聋音哑都不伦。","由子前身谤经文。","论说道士毁圣人。","在恶必报受罪缘。","但勤自责莫怨天。"]},{"t":"老君十六变词 其十一","f":"古风","c":["十一变之时。","生在南方阎浮地。","造作天地有作为。","化生万物由婴儿。","阴阳相对共相随。","众生禀气各自为。","番息众多满地池。","生活自卫由乘靡。","劫数灭尽一时亏。","洪水滔天到月支。","选擢种民留伏羲。","思之念之立僧秪。","唯有大圣共相知。"]},{"t":"老君十六变词 其十二","f":"古风","c":["十二变之时。","生在西南在黄昏。","时人厌贱还?身。","善权方略更受新。","寄胎托俗蟒蛇身。","胎中诵经不遇人。","左胁而出不由关。","堕地七步杂秽间。","九龙洗浴人不闻。","国王欢喜立东宫。","与迎新妇守衢夷。","八百伎女营乐身。","八研四升不破禅。","破散库藏施贫人。","道十八人诣宫门。","贾作大丑婆罗门。","借问太子何时还。","王心不语动王情。","骑王白象触王瞋。","先师知意不与言。","?著擅特在丘。","投身饿虎求道门。","变为白狗数百身。","稽骨须弥示后人。","传语后学须精勤。","莫贪秽辱丧子身。","沉累六趣更生难。","不信我语至时看。"]},{"t":"老君十六变词 其十三","f":"古风","c":["十三变之时。","变形易体在罽宾。","从天而下无根元。","号作弥勒金刚身。","胡人不识举邪神。","兴兵动众围圣人。","积薪国北烧老君。","太上慈悯怜众生。","渐渐诱进说法轮。","剔其须发作道人。","横被无领涅槃僧。","蒙头著领待老君。","手捉锡杖惊地虫。","卧便思神起诵经。","佛气错乱欲东秦。","梦应明帝张愆迎。","白象驮经诣洛城。","汉家立子无人情。","舍家父母习沙门。","亦无至心逃避兵。","不玩道法贪治生。","搦心不坚还俗经。","八万四千应罪缘。","破塔怀庙诛道人。","打?铜像削取金。","未荣几时还造新。","虽得存立帝恐心。"]},{"t":"老君十六变词 其十四","f":"古风","c":["十四变之时。","变形易像在金卫。","沙门闱城说经偈。","至著罪人未可济。","胡人闻之心恐怪。","将从群党来朝拜。","叩头悔过求受戒。","克肌克骨誓不退。","烧指练臂自盟誓。","男不妻娶坐思禅。","死为尸陁喂鹰鹯。","迁神涅槃舍利弗。","骨得八百升散诸国。","如此迁达离烦欲。","苦身求道立可得。"]},{"t":"老君十六变词 其十五","f":"古风","c":["十五变之时。","西向教化到罽宾。","胡国相厘还迦夷。","侵境暴耗买育人。","男子守塞忧婆夷。","吾入国中作善词。","说化男子受三归。","渐渐诱进说法轮。","剔其须发作道人。","阳为和上阴阿尼。","假作父母度僧尼。","师徒相度理无私。","迁神涅槃归紫微。","四镇安穆和我神。","胡人思念长吁啼。","铸作金像法我形。","三时入礼求长生。","寂寂寞寞不应人。","低头视地仰看天。","大圣正真何时还。"]},{"t":"老君十六变词 其十六","f":"古风","c":["十六变之时。","生在蒲林号有遮。","大富长者树提阇。","有一手巾像龙蛇。","遣风吹去到王家。","国王得之大叹吒。","兴兵动众来向家。","离舍百里见莲花。","国有审看一月夜。","王心恶之欲破家。","忽然变化白净舍。","出家求道号释迦。"]},{"t":"老君十六变词 其十七","f":"古风","c":["五百岁之时。","乘龙驾虎道得昌。","汉地广大历记长。","三十六人计弟兄。","超度北阙云中翔。","新卢酒出俱行尝。","娥媚出边作细昌。","当此之时乐未央。","伊耶乐生寿命长。"]},{"t":"老君十六变词 其十八","f":"古风","c":["六百岁之时。","一世以去二世归。","城郭如故时人非。","观者众多知我谁。","死生各异令人悲。","何不学道世欲衰。","踟蹰西北长吁谁。","伊耶乐生治太微。"]},{"t":"斛律丰乐歌","f":"五言绝句","c":["朝亦饮酒醉。","暮亦饮酒醉。","日日饮酒醉。","国计无取次。"]},{"t":"兖州民为郑氏父子歌","f":"古风","c":["大郑公。","小郑公。","相去五十载。","风教尚犹同。"]},{"t":"邯郸郭公歌","f":"古风","c":["邯郸郭公九十九。","技两渐尽入滕口。","大儿缘高冈。","雉子东南走。","不信吾言时。","当看岁在酉。"]},{"t":"济北民为崔伯谦歌","f":"古风","c":["崔府君。","能治政。","易鞭鞭。","布威德。","民无争。"]},{"t":"文宣时谣","f":"五言古诗","c":["马子入石室。","三千六百日。"]},{"t":"废帝时童谣三首 其一","f":"古风","c":["白头羊毣秃。","羖䍽历头生角。"]},{"t":"废帝时童谣三首 其二","f":"古风","c":["羊羊吃野草。","不吃野草远我道。","不远打尔脑。"]},{"t":"废帝时童谣三首 其三","f":"古风","c":["阿?姑。","祸也。","道人姑夫。","死也。"]},{"t":"孝昭时童谣","f":"七言古诗","c":["中兴寺内白凫翁。","四方侧听声雍雍。","道人闻之夜打钟。"]},{"t":"武成殂后谣","f":"五言绝句","c":["千钱买果园，中有芙蓉树。","破家不分明，莲子随它去。"]},{"t":"武平元年童谣","f":"古风","c":["狐截尾。","你欲除我我除你。"]},{"t":"武平中童谣","f":"古风","c":["和士开。","七月三十日。","将你向南台。"]},{"t":"武平中童谣","f":"古风","c":["七月刈禾伤早。","九月吃糕正好。","十月洗荡饭瓮。","十一月出却赵老。"]},{"t":"曲严祖珽为斛律光造谣二首 其一","f":"五言古诗","c":["百升飞上天。","明月照长安。"]},{"t":"曲严祖珽为斛律光造谣二首 其二","f":"古风","c":["高山不推自崩。","槲木不扶自竖。","盲老公背上下大斧。","饶舌老母不得语。"]},{"t":"武成时童谣","f":"七言古诗","c":["九龙母死不作孝。"]},{"t":"北齐末邺中童谣","f":"七言古诗","c":["金作扫帚玉作把，净扫殿屋迎西家。"]},{"t":"武平末童谣","f":"五言古诗","c":["黄花势欲落。","清尊但满酌。"]},{"t":"徐之范引童谣","f":"古风","c":["周里跂求伽。","豹祠嫁石婆。","斩冢作媒人。","唯得一量紫綖靴。"]},{"t":"杨子术引谣言","f":"古风","c":["卢十六。","稚十四。","犍子拍头三十二。"]},{"t":"清河民为曲堤语","f":"古风","c":["宁度江吴会稽。","不历成公曲堤。"]},{"t":"齐人为苏珍之宋世轨语","f":"七言古诗","c":["决定嫌疑苏珍之，视表见里宋世轨。"]},{"t":"省中为祖珽裴让之语","f":"七言古诗","c":["多奇多能祖孝徵，能赋能诗裴让之。"]},{"t":"文林馆中为陆乂语","f":"古风","c":["五经无对。","有陆乂。"]},{"t":"颜之推引俗谚论教子","f":"古风","c":["教妇初来。","教儿婴孩。"]},{"t":"颜之推引谚论治家","f":"五言古诗","c":["落索阿姑餐。"]},{"t":"时人为陈元康语","f":"古风","c":["三崔二张。","不如一康。"]},{"t":"邺下为陆仲让语","f":"七言古诗","c":["讲义两行得中郎。"]},{"t":"时人为唐邕白建言","f":"七言古诗","c":["并州赫赫唐与白。"]},{"t":"时人为裴皇甫二姓兄弟语","f":"古风","c":["诹胜于让。","和不如亮。"]},{"t":"时人为冯祖赵三氏子语","f":"古风","c":["冯祖及赵，秽我凤池。"]},{"t":"御史台中为宋游道语","f":"古风","c":["见贼能讨。","宋游道。"]},{"t":"时人为宋游道陆操语","f":"古风","c":["游道狝猴面。","陆操科斗形。","意识不关貌。","何谓丑者必无情。"]},{"t":"邺下为李氏兄弟语","f":"五言古诗","c":["学则浑绘纬，口则绘纬浑。"]},{"t":"时人为义深语","f":"古风","c":["剑戟森森。","李义深。"]},{"t":"时人为阳休之语","f":"古风","c":["能赋能诗。","阳休之。"]},{"t":"时人为阴凤语","f":"七言古诗","c":["阴生读书不免痴。","不识双凤脱人衣。"]},{"t":"时人为法上谚","f":"古风","c":["沙弥若来。","高座逢灾。"]},{"t":"大禘圜丘及北郊歌辞十三首 其一 肆夏","f":"古风","c":["肇应灵序，奄字黎民。","乃朝万国，爰徵百神。","只展方望，幽显咸臻。","礼崇声协，贽列圭陈。","翼差鳞次，端拱垂绅。","来趋动色，式赞天人。"]},{"t":"大禘圜丘及北郊歌辞十三首 其二 高明乐","f":"古风","c":["惟神鉴矣，皇灵肃止。","圜璧展事，成文即始。","士备八能，乐合六变。","风凑伊雅，光花袭荐。","宸卫腾景，灵驾霏烟。","严坛生白，绮席凝玄。"]},{"t":"大禘圜丘及北郊歌辞十三首 其三 昭夏乐","f":"古风","c":["刚柔凤位，惟皇配之。","言肃其礼，念畅在兹。","饰牲举兽，载歌且舞。","既设伊腯，致精灵府。","物色惟典，斋沐加恭。","宗族咸暨，罔不率从。"]},{"t":"大禘圜丘及北郊歌辞十三首 其四 昭夏乐","f":"古风","c":["展礼上月，肃事应时。","茧栗为用，交畅有期。","弓矢斯发，瓮簝将事。","圆神致祀，率由先志。","和以銮刀，臭以血膋。","至哉敬矣，厥义孔高。"]},{"t":"大禘圜丘及北郊歌辞十三首 其五 皇夏乐","f":"古风","c":["帝敬昭宣，皇诚萧致。","玉帛齐轨，屏摄咸次。","三垓上列，四陛旁升。","龙陈万骑，凤动千乘。","神仪天蔼，睟容离曜。","金根停轸，奉光先导。"]},{"t":"大禘圜丘及北郊歌辞十三首 其六 皇夏乐","f":"古风","c":["紫坛云暧，绀幄霞褰。","我其陟止，载致其虔。","百灵竦听，万国咸仰。","人神咫尺，玄应肸蚃。"]},{"t":"大禘圜丘及北郊歌辞十三首 其七 高明乐","f":"古风","c":["上下眷，旁午从。","爵以质，献以恭。","咸斯畅，乐唯雍。","孝敬阐，临万邦。"]},{"t":"大禘圜丘及北郊歌辞十三首 其八 高明乐","f":"古风","c":["自天子之，会昌神道。","丘陵肃事，克光天保。","九关洞开，百灵环列。","八樽呈备，五声投节。"]},{"t":"大禘圜丘及北郊歌辞十三首 其九 武德乐","f":"古风","c":["配神登圣，主极尊灵。","敬宣昭烛，咸达窅冥。","礼弘化定，乐赞功成。","穰穰介福，下被群生。"]},{"t":"大禘圜丘及北郊歌辞十三首 其十 皇夏乐","f":"五言古诗","c":["皇心缅且感，吉蠲奉至诚。","赫哉光盛德，乾坤照百灵。","报福归昌运，承佑播休明。","风云驰九域，龙蛟跃四溟。","浮幕呈光气，俪象烛华精。","护武方知耻，韶夏仅同声。"]},{"t":"大禘圜丘及北郊歌辞十三首 其十一 高明乐","f":"古风","c":["献享毕，悬佾周。","神之驾，将上游。","超斗极，绝河流。","怀万国，宁九州。","欣帝道，心顾留。","匝上下，荷皇休。"]},{"t":"大禘圜丘及北郊歌辞十三首 其十二 昭夏乐","f":"古风","c":["玄黄覆载，元首照临。","合德致礼，有契其心。","敬申事阕，絜诚共报。","玉帛载升，棫朴斯燎。","寥廓幽暧，播以馨香。","皇灵惟监，降福无疆。"]},{"t":"大禘圜丘及北郊歌辞十三首 其十三 皇夏乐","f":"古风","c":["天大亲严，匪敬伊孝。","永言肆飨，宸明增耀。","阳丘既畅，大典逾光。","乃安斯息，钦若旧章。","天回地旋，鸣銮引警。","且万且亿，皇历惟永。"]},{"t":"五郊乐歌五首 其一 青帝高明乐","f":"古风","c":["岁云献，谷风归。","斗东指，雁北飞。","电鞭激，雷车遽。","虹旌靡，青龙驭。","和气洽，具物滋。","翻降止，应帝期。"]},{"t":"五郊乐歌五首 其二 赤帝高明乐","f":"古风","c":["婺女司旦。","仲吕宣。","朱精御节。","离景延。","根荄俊茂。","温风发。","柘火风水。","应炎月。","执衡长物。","德孔昭。","赤旗电曳。","会今朝。"]},{"t":"五郊乐歌五首 其三 黄帝高明乐","f":"五言律诗","c":["居中匝五运，乘衡毕四时。","含养滋群物，协德固皇基。","啴缓契王风，持载符君德。","良辰动灵驾，承祀昌邦国。"]},{"t":"五郊乐歌五首 其四 白帝高明乐","f":"古风","c":["风凉露降。","驰景飏寒精。","山川摇落。","平秩在西成。","盖藏成积。","烝民被嘉祉。","从享来仪。","鸿休溢千祀。"]},{"t":"五郊乐歌五首 其五 黑帝高明乐","f":"古风","c":["虹藏雉化。","告寒。","冰壮地坼。","年殚。","日次月纪。","方极。","九州万邦。","献力。","叶光是纪。","岁穷。","微阳潜兆。","方融。","天子赫赫。","明圣。","享神降福。","惟敬。"]},{"t":"祀五帝于明堂乐歌十一首 其一 肆夏乐","f":"古风","c":["国际崇祀，严恭有闻。","荒华胥暨，乐我大君。","冕瑞有列，禽帛载叙。","群后师师，威仪容与。","执礼辨物，司乐考章。","率由靡坠，休有烈光。"]},{"t":"祀五帝于明堂乐歌十一首 其二 高明乐","f":"古风","c":["祖德光，国图昌。","祗上帝，礼四方。","辟紫宫，动华阙。","龙虎奋，风云发。","飞朱雀，从玄武。","携日月，带雷雨。","耀宇内，溢区中。","眷帝道，感皇风。","帝道康，皇风扇。","粢盛列，椒醑荐。","神且宁，会五精。","归福禄，幸闾亭。"]},{"t":"祀五帝于明堂乐歌十一首 其三 武德乐","f":"古风","c":["我惟我祖，自天之命。","道被归仁，时屯启圣。","运钟千祀，授手万姓。","夷凶掩虐，匡颓翼正。","载经载营，庶士咸宁。","九功以洽，七德兼盈。","丹书入告，玄玉来呈。","露甘泉白，云郁河清。","声教咸往，舟车毕会。","仁加有形，化浃无外。","严亲惟重，陟配惟大。","既佑斯歌，率土攸赖。"]},{"t":"祀五帝于明堂乐歌十一首 其四 昭夏乐","f":"古风","c":["孝享不匮，精洁临年。","涤牢委溢，形色博牷。","于以用之，言承歆祀。","肃肃威仪，敢不敬止。","载饬载省，惟牛惟羊。","明神有察，保兹万方。"]},{"t":"祀五帝于明堂乐歌十一首 其五 昭夏乐","f":"古风","c":["我将宗祀，夤献厥诚。","鞠躬如在，侧听无声。","荐色斯纯，呈气斯臭。","有涤有濯，惟神其佑。","五方来格，一人多祉。","明德惟馨，于穆不已。"]},{"t":"祀五帝于明堂乐歌十一首 其六 皇夏乐","f":"古风","c":["象乾上构，仪坤下基。","集灵崇祖，永言孝思。","室陈簋豆，庭罗悬佾。","夙夜畏威，保兹贞吉。","舞贵其夜，歌重其升。","降斯百禄，惟飨惟应。"]},{"t":"祀五帝于明堂乐歌十一首 其七 高明乐","f":"古风","c":["度几筵，辟牖户。","礼上帝，感皇祖。","酌惟絜，涤以清。","荐心款，达神明。"]},{"t":"祀五帝于明堂乐歌十一首 其八 高明乐","f":"古风","c":["帝精来降，应我明德。","礼殚义展，流祉邦国。","既受多祉，实资孝敬。","祀谒其诚，荷天休命。"]},{"t":"祀五帝于明堂乐歌十一首 其九 皇夏乐","f":"古风","c":["恭祀洽。","盛礼宣。","英猷烂层景。","广泽同深泉。","上灵钟百福。","群神归万年。","月轨咸梯岫。","日域尽浮川。","瑞鸟飞玄扈。","潜鳞跃翠连。","皇家膺宝历。","两地复参天。"]},{"t":"祀五帝于明堂乐歌十一首 其十 高明乐","f":"古风","c":["青阳奏，发朱明。","歌西皓，唱玄冥。","大礼罄，广乐成。","神心怿，将远征。","饰龙驾，矫凤旌。","指阊阖，憩层城。","出温谷，迈炎庭。","跨西汜，过北溟。","忽万亿，耀光精。","比电骛，与雷行。","嗟皇道，怀万灵。","固王业，震天声。"]},{"t":"祀五帝于明堂乐歌十一首 其十一 皇夏乐","f":"古风","c":["文物备矣，声明有章。","登荐惟肃，礼邈前王。","鬯齐云终，折旋告罄。","穆穆旒冕，蕴诚毕敬。","屯卫按部，銮跸回途。","暂留紫殿，将及清都。"]},{"t":"享庙乐辞十八首 其一 肆夏乐","f":"古风","c":["霜凄雨畅，烝哉帝心。","有敬其祀，肃事惟歆。","昭昭车服，济济衣簪。","鞠躬贡酎，磬折奉琛。","差以五列，和以八音。","式祗王度，如玉如金。"]},{"t":"享庙乐辞十八首 其二 高明登歌乐","f":"古风","c":["日卜惟吉，辰择其良。","奕奕清庙，黼黻周张。","大吕为角，应钟为羽。","路鼗阴竹，德歌昭舞。","祀事孔明，百神允穆。","神心乃顾，保兹介福。"]},{"t":"享庙乐辞十八首 其三 昭夏乐","f":"古风","c":["大祀云事，献奠有仪。","既歌既展，赞顾迎牺。","执从伊竦，刍饰惟栗。","俟用于庭，将升于室。","且握且骍，以致其诚。","惠我贻颂，降祉千龄。"]},{"t":"享庙乐辞十八首 其四 昭夏乐","f":"古风","c":["缅彼遐慨，悠然永思。","留连七享，缠绵四时。","神升魄沈，靡闻靡见。","阴阳载俟，臭声兼荐。","祖考其鉴，言萃王休。","降神敷锡，百福是由。"]},{"t":"享庙乐辞十八首 其五 皇夏乐","f":"古风","c":["齐居严严，夙驾层闱。","车辂垂彩，旒衮腾辉。","耸诚载仰，翘心有慕。","洞洞自形，斤斤表步。","閟宫有邃，神道依稀。","孝心缅邈，爰属爰依。"]},{"t":"享庙乐辞十八首 其六 登歌乐","f":"古风","c":["太室窅窅，神居宿设。","郁鬯惟芬，圭璋惟洁。","彝斝应时，龙蒲代用。","藉茅无咎，福禄攸降。","端感会事，俨思修礼。","齐齐勿勿，俄俄济济。"]},{"t":"享庙乐辞十八首 其七 登歌乐","f":"古风","c":["我祠我祖，永惟厥先。","炎农肇圣，灵祉蝉联。","霸图中造，帝业方宣。","道昌基构，抚运承天。","奄家六合，爰光八埏。","尊神致礼，孝思惟缠。","寒来暑反，惕荐在年。","匪敬伊慕，备物不愆。","设虡设业，鼗鼓填填。","辟公在位，有容伊虔。","登歌启佾，下管应悬。","厥容无爽，幽明肃然。","诚匝厚地，和达穹玄。","既调风雨，载协山川。","周庭有列，汤孙永延。","教声惟被，迈后光前。"]},{"t":"享庙乐辞十八首 其八 始基乐恢祚舞","f":"古风","c":["克明克俊，祖武惟昌。","业弘营土，声被海方。","有流厥德，终耀其光。","明神幽赞，景祚攸长。"]},{"t":"享庙乐辞十八首 其九 始基乐恢祚舞","f":"古风","c":["显允盛德，隆我前构。","瑶源弥泻，琼根愈秀。","诞惟有族，丕绪克茂。","大业崇新，洪基增旧。"]},{"t":"享庙乐辞十八首 其十 始基乐恢祚舞","f":"古风","c":["祖德丕显，明哲知几。","豹变东国，鹊起西归。","礼申官次，命改朝衣。","敬思孝享，多福无违。"]},{"t":"享庙乐辞十八首 其十一 始基乐恢祚舞","f":"古风","c":["兆灵有业，潜德无声。","韬光戢耀，贯幽洞冥。","道弘舒卷，施博藏行。","缅追岁事，夜遽不宁。"]},{"t":"享庙乐辞十八首 其十二 始基乐恢祚舞祖","f":"古风","c":["皇皇祖德，穆穆其风。","语嘿自己，明睿在躬。","荷天之锡，圣表克隆。","高山作矣，实祚其崇。","离光旦旦，载焕载融。","感荐惟永，神保无穷。"]},{"t":"享庙乐辞十八首 其十三 武德乐昭烈舞","f":"古风","c":["天造草昧，时难纠纷。","孰拯斯溺，靡救其焚。","大人利见，纬武经文。","顾指维极，吐吸风云。","开天辟地，峻岳夷海。","冥工掩迹，上德不宰。","神心有应，龙化无待。","义征九服，仁兵告凯。","上平下成，靡或不宁。","匪王伊帝，偶极崇灵。","享亲则孝，洁祀惟诚。","礼备乐序，肃赞神明。"]},{"t":"享庙乐辞十八首 其十四 文德乐宣政舞","f":"古风","c":["圣武丕基，睿文显统。","眇哉神启，郁矣天纵。","道则人弘，德云迈种。","昭冥咸叙，崇深毕综。","自中徂外，经朝庇野。","政反沦风，威还缺雅。","帝作穆穆，格于上下。","维享维宗，来鉴来假。"]},{"t":"享庙乐辞十八首 其十五 文正乐光大舞","f":"古风","c":["玄历已谢，苍灵告期。","图玺有属，揖让惟时。","龙升兽变，弘我帝基。","对扬穹昊，寔启雍熙。","钦若皇猷，永怀王度。","欣赏斯穆，威刑允措。","轨物俱宣，宪章咸布。","俗无邪指，下归正路。","茫茫九域，振以乾纲。","混通华裔，配括天壤。","作礼视德，列乐传响。","荐祀惟虔，衣冠载仰。"]},{"t":"享庙乐辞十八首 其十六 皇夏乐","f":"古风","c":["孝心翼翼，率礼兢兢。","时洗时荐，或降或升。","在堂在户，载湛载凝。","多品斯奠，备物修膺。","兰芬敬挹，玉俎恭承。","受祭之佑，如彼冈陵。"]},{"t":"享庙乐辞十八首 其十七 高明乐","f":"古风","c":["仰榱桷，慕衣冠。","礼云罄，祀将阑。","神之驾，纷奕奕。","乘白云，无不适。","穷昭域，极幽涂。","归帝祉，眷皇都。"]},{"t":"享庙乐辞十八首 其十八 皇夏","f":"古风","c":["礼行斯毕，乐奏以终。","受嘏先退，载畅其衷。","銮轩循辙，麾旌复路。","光景徘徊，弦歌顾慕。","灵之相矣，有锡无疆。","国图日竞，家历天长。"]},{"t":"元会大飨歌十首 其一 肆夏","f":"古风","c":["昊苍眷命，兴王统天。","业高帝始，道貌皇先。","礼成化穆，乐合风宣。","宾朝荒夏，对扬穹玄。"]},{"t":"元会大飨歌十首 其二 皇夏","f":"古风","c":["夏正肇旦，周物充庭。","具僚在位，俯伏无声。","大君穆穆，宸仪动睟。","日煦天回，万灵胥萃。"]},{"t":"元会大飨歌十首 其三 皇夏","f":"古风","c":["天子南面，乾覆离明。","三千咸列，万国填并。","犹从禹会，如次汤庭。","奉兹一德，上下和平。"]},{"t":"元会大飨歌十首 其四 皇夏","f":"古风","c":["我应天历，四海为家。","协同内外，混一戎华。","鹤盖龙马，风乘云车。","夏章夷服，其会如麻。","九宾有仪，八音有节。","肃肃于位，饮和在列。","四序氤氲，三光昭晰。","君哉大矣，轩唐比辙。"]},{"t":"元会大飨歌十首 其五 皇夏","f":"古风","c":["皇运应箓，廓定区寓。","受终以文，构业以武。","尧昔命舜，舜亦命禹。","大人驭历，重规沓矩。","钦明在上，昭纳八夤。","从灵体极，诞圣穷神。","化生群品，陶育烝人。","展礼肆乐，协此元春。"]},{"t":"元会大飨歌十首 其六 肆夏","f":"古风","c":["万方咸暨，三揖以申。","垂旒冯玉，五瑞交陈。","拜稽有章，升降有节。","圣皇负扆，虞唐比烈。"]},{"t":"元会大飨歌十首 其七 上寿曲","f":"古风","c":["仰三光。","奏万寿。","人皇御六气。","天地同长久。"]},{"t":"元会大飨歌十首 其八 登歌三曲","f":"古风","c":["大齐统历，道化光明。","马图呈宝，龟箓告灵。","百蛮非众，八荒非逖。","同作尧人，俱包禹迹。"]},{"t":"元会大飨歌十首 其九","f":"古风","c":["天覆地载，成以四时。","惟皇是则，比大于兹。","群星拱极，众川赴海。","万寓骏奔，一朝咸在。"]},{"t":"元会大飨歌十首 其十","f":"古风","c":["齐之以礼，相趋帝庭。","应规蹈矩，玉色金声。","动之以乐，和风四布。","龙申凤舞，鸾歌麟步。"]},{"t":"食举乐十曲 其一","f":"古风","c":["三端正启。","万方观礼。","具物充庭。","二仪合体。","百华照晓。","千门洞晨。","或华或裔。","奉贽惟新。","悠悠亘六合。","圆首莫不臣。","仰施如雨。","晞和犹春。","风化表笙镛。","歌讴被琴瑟。","谁言文轨异。","今朝混为一。"]},{"t":"食举乐十曲 其二","f":"古风","c":["彤庭烂景。","丹陛流光。","怀黄绾白。","鹓鹭成行。","文赞百揆。","武镇四方。","折冲鼓雷电。","替辇协阴阳。","大矣哉。","道迈上皇。","陋五帝。","狭三皇。","穷礼物。","该乐章。","序冠带。","垂衣裳。"]},{"t":"食举乐十曲 其三","f":"古风","c":["天壤和。","家国穆。","悠悠万类。","咸孕育。","契冥化。","侔大造。","灵效珍。","神归宝。","兴云气。","飞龙苍。","麟一角。","凤五光。","朱雀降。","黄玉表。","九尾驯。","三足扰。","化之定。","至矣哉。","瑞感德。","四方来。"]},{"t":"食举乐十曲 其四","f":"古风","c":["囹圄空。","水火菽粟。","求贤振滞。","弃珠玉。","衣不靡。","宫以卑。","当阳端嘿。","垂拱无为。","云云万有。","其乐不訾。"]},{"t":"食举乐十曲 其五","f":"古风","c":["嗟此举时。","逢至道。","肖形咸自持。","赋命无伤夭。","行气进皇舆。","游龙服帝皂。","圣主宁区宇。","乾坤永相保。"]},{"t":"食举乐十曲 其六","f":"古风","c":["牧野征。","鸣条战。","大齐家万国。","拱揖应终禅。","奥主廓清都。","大君临赤县。","高居深视。","当扆正殿。","旦暮之期。","今一见。"]},{"t":"食举乐十曲 其七","f":"古风","c":["两仪分，牧以君。","陶有象，化无垠。","大齐德，邈谁群。","超凤火，冠龙云。","露以洁，风以薰。","荣光至，气氤氲。"]},{"t":"食举乐十曲 其八","f":"古风","c":["神化远，人灵协。","寒暑调，风雨燮。","披泥检，受图谍。","图谍启，期运昌。","分四序，缀三光。","延宝作，眇无疆。"]},{"t":"食举乐十曲 其九","f":"古风","c":["惟皇道，升平日。","河水清，海不溢。","云干吕，风入律。","驱黔首，入仁寿。","与天高，并地厚。"]},{"t":"食举乐十曲 其十","f":"古风","c":["形以厝，颂声扬。","皇情邈，眷汾襄。","岱山高，配林壮。","亭亭耸，云云望。","旆葳蕤，驾骙骙。","刊金阙，奠玉龟。"]},{"t":"皇夏","f":"古风","c":["礼终三爵，乐奏九成。","允也天子，穹壤和平。","载色载笑，反寝晏息。","一人有祉，百神奉职。"]},{"t":"文武舞歌四首 其一 文舞阶步辞","f":"古风","c":["我后降德，肇峻皇基。","摇铃大号，振铎命期。","云行雨洽，天临地持。","茫茫区宇，万代一时。","文来武肃，成定于兹。","象容则舞，歌德言诗。","锵锵金石，列列匏丝。","凤仪龙至，乐我雍熙。"]},{"t":"文武舞歌四首 其二 文舞辞","f":"古风","c":["皇天有命，归我大齐。","受兹华玉，爰锡玄圭。","奄家环海，实子蒸黎。","图开宝匣，检封芝泥。","无思不顺，自东徂西。","教南暨朔，罔敢或携。","比日之明，如天之大。","神化之洽，率土无外。","眇眇舟车，华戎毕会。","祠我春秋，服我冠带。","仪协震象，乐均天籁。","蹈武在庭，其容蔼蔼。"]},{"t":"文武舞歌四首 其三 武舞阶步辞","f":"古风","c":["大齐统历，天鉴孔昭。","金人降泛，火凤来巢。","眇均虞德，干戚降苗。","夙沙攻主，归我轩朝。","礼符揖让，乐契咸韶。","蹈扬惟序，律度时调。"]},{"t":"文武舞歌四首 其四 武舞辞","f":"古风","c":["天眷横流，宅心玄圣。","祖功宗德，重光袭映。","我皇恭己，诞膺灵命。","宇外斯烛，域中咸镜。","悠悠率土，时惟保定。","微微动植，莫违其性。","仁丰庶物，施洽群生。","海宁洛变，契此休明。","雅宣茂烈，颂纪英声。","铿锽钟鼓，掩抑箫笙。","歌之不足，舞以礼成。","铄矣王度，缅迈千龄。"]},{"t":"武阳山遗咏","f":"古风","c":["登武阳。","观乐薮。","峨岭千蕤洋湖口。","命飞螭。","驾白驹。","临天水。","心踟蹰。","千载后。","不知如。"]},{"t":"周初童谣","f":"七言古诗","c":["白杨树头金鸡鸣。","秪有阿舅无外甥。"]},{"t":"玉浆泉谣","f":"古风","c":["我有丹阳，山出玉浆。","济我民夷，神乌来翔。"]},{"t":"蜀中为于仲文语","f":"七言古诗","c":["明断无双有于公，不避强御有次武。"]},{"t":"时人为裴诹柳虬语","f":"古风","c":["经府裴诹。","南省柳虬。"]},{"t":"诸生为吕思礼语","f":"古风","c":["讲书论易。","其锋难敌。"]},{"t":"周地图记引语","f":"古风","c":["南山瀑布。","非朝即暮。"]},{"t":"青帝歌","f":"五言古诗","c":["东望重拜手，苍帝玉皇君。","灵风鼓橐签，育物布元春。","云龙辔严驾，玉衡拥琼轮。","枯萌泛沾及，大惠无不均。","万仙歌以道，委曲戒天人。","心根迷自固，拱跽戴鸿仁。"]},{"t":"白帝歌","f":"五言古诗","c":["六甲抱金关，七政守灵坛。","流铃掷化火，威剑巨龙蟠。","恳彼素灵真，明宪孰敢干。","束制妖鬼魔，凛落霄风寒。","沴气既已息，万天俄而安。","真俦荷太庇，抵颡相歌让。"]},{"t":"赤帝歌","f":"五言古诗","c":["太景开玉枢，洞堂启金除。","骞林荫瑶砌，丹鸾踏琼株。","宝房名曲丽，明珰神所居。","飞游豁云道，引目盻真都。","天日永不息，重烟锁青庐。","太上敕印开，帕几罗简书。","裨风树玄化，殷辛谅有馀。"]},{"t":"黑帝歌","f":"楚辞体","c":["无质统有物，渊兮上帝心。","不启不发道，蕴妙化机深。","恐尔漏未尽，阴想忽侵淫。","转轮无涯波，苦道相迷寻。","万年常谨约，一旦自湮沉。","无冲落鬼境，殃遣不可任。"]},{"t":"黄帝歌","f":"五言古诗","c":["黄天拱中宸，控驾玉化根。","翘机贯亿历，洞朗辟四门。","大有混皇真，糺制星宿魂。","非帝道不运，有方赖之存。","威忿即霜秋，和预为阳春。","生成握元纪，仰荷戴无垠。"]},{"t":"金章太守章","f":"五言古诗","c":["大魔乘空发，万精骇神庭。","托化谣歌章，随变入无名。","嚣气何纷纷，秽道当涂生。","云中舍朱宫，北帝踊神兵。","鼓洋自知道，玄运来相征。","上景御飞辔，迅驾检云营。","促校北帝录，收执群魔名。","豁落张天罗，放威掷流铃。","金真辅空洞，玉光焕八冥。","金玄守上宫，神虎戮天精。","剪灭万妖气，亿亿悉齐平。","上承九天信，啸命靡不倾。","招真究三洞，慧诵朗自清。","八道望玄■，七转纬天经。","混合第一真，拔度七祖程。","消灭五苦根，反魂更受荣。","金光曜寂室，神仙自然生。","香华散玉宇，烟气彻玉京。","帝遣徘徊辇，三元降绿軿。","迅驾腾九玄，朝我玉皇庭。"]},{"t":"步虚辞十首 其一","f":"五言古诗","c":["稽首礼太上，烧香归虚无。","流明随我回，法轮亦三周。","玄愿四大兴，灵庆及王侯。","七祖生天堂，煌煌曜景敷。","啸歌观大漠，天乐适我娱。","斋馨无上德，下仙不与俦。","妙想明玄觉，诜诜乘虚游。"]},{"t":"步虚辞十首 其二","f":"五言古诗","c":["旋行蹑云纲，乘虚步玄纪。","吟咏帝一尊，百关自调理。","俯命八海童，仰携高仙子。","诸天散香华，翛然灵风起。","宿愿定命根，故致高标拟。","欢乐太上前，万劫犹未始。"]},{"t":"步虚辞十首 其三","f":"五言古诗","c":["嵯峨玄都上，十方宗皇一。","苕苕天宝台，光明焰流日。","炜烨玉林华，茜粲曜珠实。","常念餐元精，炼液固形质。","金光散紫微，窈窕大乘逸。"]},{"t":"步虚辞十首 其四","f":"五言古诗","c":["俯仰存太上，华景秀丹田。","左顾提郁仪，右盼携结璘。","六度冠梵行，道德随日新。","宿命积福应，闻经若玉亲。","天挺超世才，乐诵希微篇。","冲虚太和气，吐纳流霞津。","胎息静百关，寥寥究三便。","泥丸洞明景，遂成金华仙。","魔王教授事，故能朝诸天。","皆从斋戒起，累功结宿缘。","飞行凌太虚，提携高上人。"]},{"t":"步虚辞十首 其五","f":"五言古诗","c":["控辔适十方，旋憩玄景阿。","仰观劫刃台，俯盻紫云罗。","逍遥太上京，相与坐莲华。","积学为真人，恬然荣卫和。","永享无期寿，万椿奚足多。"]},{"t":"步虚辞十首 其六","f":"五言古诗","c":["大道师玄寂，升仙友无英。","公子度灵符，太一奉洞章。","舍利曜金姿，龙驾欻来迎。","天尊盻云舆，飘飘乘虚翔。","香花若飞雪，纷蔼茂玄梁。","头脑礼金阙，携手邀玉京。"]},{"t":"步虚辞十首 其七","f":"五言古诗","c":["骞树圆景园。","焕烂七宝林。","夭兽三百名。","师子巨万寻。","飞龙踯躅吟。","神凤应节鸣。","灵风扇奇华。","清香散人衿，自无高仙才。","焉能耽此心。"]},{"t":"步虚辞十首 其八","f":"五言古诗","c":["严我九龙驾，乘虚以逍遥。","八天如指掌，六合何足辽。","众仙诵洞玄，太上唱清谣。","香花随风散，玉音成紫霄。","五苦一时迸，八难顺经寥。","妙哉灵宝圃，兴此大法桥。"]},{"t":"步虚辞十首 其九","f":"五言律诗","c":["天真帝一宫，蔼蔼冠耀灵。","流焕法轮网，旋空入无形。","虚皇拊云璈，众真诵洞经。","高仙凛手赞，弥劫保利贞。"]},{"t":"步虚辞十首 其十","f":"五言古诗","c":["至真无所待，时或辔飞龙。","长斋会玄都，鸣玉叩琼钟。","十华诸仙集，紫烟结成宫。","宝盖罗太上，真人把芙蓉。","散花陈我愿，握节徵魔王。","法鼓会群仙，灵唱弥不同。","无可无不可，思与希微通。"]},{"t":"三徒五苦辞 其一","f":"五言律诗","c":["三才及万物，倚伏各有龄。","终始待劫数，福尽天地倾。","往反于五道，苦哉更死生。","辗转三徒中，去来与祸并。"]},{"t":"三徒五苦辞 其二","f":"五言律诗","c":["大贤慎兹诫，忍性念割情。","愚夫不信法，罪痛常自婴。","吾念世无己，今故重告明。","若欲度斯患，归命太上经。"]},{"t":"三徒五苦辞 其三","f":"五言律诗","c":["罪福不由他，谅自发尔声。","大贤故闭口，欲绝诸恶缘。","灭念归兼至，倚伏待长泯。","弘道以安世，终当见正真。"]},{"t":"三徒五苦辞 其四","f":"五言律诗","c":["淫嫉为祸首，灭身之至患。","含养如此害，岂是道所安。","知恶而不革，恐必致夭残。","怀毒日斋直，令我发长叹。"]},{"t":"三徒五苦辞 其五","f":"五言律诗","c":["宿命有信然，弱丧谓之无。","皆欲眼前见，过目即言悠。","大贤明道教，惨戚悯顽夫。","依依念子苦，勤勤令我忧。"]},{"t":"三徒五苦辞 其六","f":"五言古诗","c":["人命以消尽，亦犹膏中火。","四大暂相寓，五物权时假。","盛年当勤学，趣求存告我。","福尽身神散，冥冥地狱下。","上圣畏是故，寻道度斯福。"]},{"t":"三徒五苦辞 其七","f":"五言古诗","c":["学仙行为急，奉戒制情心。","虚夷正气居，仙圣处相寻。","若不信法言，胡为栖山林。","大贤乐经戒，受之为身宝。","就学常苦晚，治身恨不早。","比当披幽迹，倏欻年已老。","执卷吸尔极，将更死痛恼。","吾故及弱龄，弃世以学道。"]},{"t":"碧落空歌","f":"五言古诗","c":["妙哉元始道，大梵敷真文。","上开龙汉劫，焕烂光彩分。","三十二天书，五老赤字传。","垂慈度生死，郁勃吐祥云。","中有长命诀，植芽炼飞仙。","开函发玄奥，稽首生精勤。","仰思高灵降，乘气归三清。"]},{"t":"魔王歌章","f":"五言古诗","c":["梵行冠太罗，淳风抗玄纪。","无形有常存，观世翻然理。","屡践不终劫，探幽度生死。","三乘通便路，清虚无尘滓。","长夜对一魂，地狱五苦解。","剑树不摇条，刀上不伤体。","门有浩劫翁，地无夭年子。","今日庆斯会，诸天并欢喜。","不胜情欣悦，高唱稽首礼。"]},{"t":"第一欲界飞空之音","f":"楚辞体","c":["人道渺渺仙道莽莽。","鬼道乐兮当人生门。","天道贵生鬼道贵终。","仙道常自吉。","鬼道常自凶。"]},{"t":"第二色界魔王之章","f":"楚辞体","c":["落落高照明气四骞，梵行诸天周回十方。","无量大神皆由我身，我有洞章万遍成仙。","仙道贵度鬼道相连，天地眇莽秽气氛氛。","三界乐兮过之常存，身入我界体入自然。","此时乐兮薄由我恩，龙汉荡荡何能别真。","我界难度故作洞文，变化飞空以试尔身。","成败懈退度者几人，笑而不度故为歌音。"]},{"t":"第三无色界魔王歌","f":"古风","c":["三界之上眇眇大罗。","上无色根云层峨峨。","唯有元始浩劫之象。","部制我界统乘玄都。","有过我界身入玉虚。","我位上王匡御众魔。","空中万变秽气纷葩。","保真者少迷惑者多。","仙道难固鬼道易邪。","人道者心谅不由他。","仙道贵实人道贵华。","尔不乐仙道。","三界那得过。","其欲转五道。","我当复奈何。"]},{"t":"陈人为齐云观歌","f":"古风","c":["齐云观。","寇来无际畔。"]},{"t":"陈初童谣","f":"五言绝句","c":["黄斑青骢马，发自寿阳涘。","来时冬气末，去日春风始。"]},{"t":"陈初童谣","f":"五言绝句","c":["御路种竹筱，萧萧已复起。","合盘贮蓬块，无复扬尘已。"]},{"t":"陈初童谣","f":"古风","c":["日西夜乌飞。","拔剑倚梁柱。","归去来。","归山下。"]},{"t":"陈宣帝时谣","f":"五言古诗","c":["大货六铢钱，叉腰哭天子。"]},{"t":"时人为张氏语","f":"古风","c":["宋称敷演，梁则卷充。","清虚学尚，种有其风。"]},{"t":"时人为贺氏兄弟语","f":"七言古诗","c":["学行可师贺德基，文质彬彬贺德仁。"]},{"t":"徐陵引谚","f":"五言古诗","c":["图官在乱世，觅富在荒年。"]},{"t":"舆地志引谚","f":"古风","c":["生东吴。","死丹徒。"]},{"t":"时人为释贞观语","f":"五言古诗","c":["钱塘有贞观。","当天下一半。"]},{"t":"夜黄","f":"五言绝句","c":["湖中百种鸟，半雌半是雄。","鸳鸯逐野鸭，恐畏不成双。"]},{"t":"夜度娘","f":"五言绝句","c":["夜来冒霜雪，晨去履风波。","虽得叙微情，奈侬身苦何。"]},{"t":"长松标","f":"五言绝句","c":["落落千丈松，昼夜对长风。","岁暮霜雪时，寒苦与谁双。"]},{"t":"双行缠 其一","f":"五言绝句","c":["朱丝系腕绳，真如白雪凝。","非但我言好，众情共所称。"]},{"t":"双行缠 其二","f":"五言绝句","c":["新罗绣行缠，足趺如春妍。","他人不言好，独我知可怜。"]},{"t":"黄督 其一","f":"五言绝句","c":["乔客他乡人，三春不得归。","愿看杨柳树，已复藏班鵻。"]},{"t":"黄督 其二","f":"五言绝句","c":["笼车度蹋衍，故人求寄载。","催牛闭后户，无预故人事。"]},{"t":"西平乐","f":"五言绝句","c":["我情与欢情，二情感苍天。","形虽胡越隔，神交中夜间。"]},{"t":"寻阳乐","f":"五言绝句","c":["鸡亭故侬去，九里新侬还。","送一却迎两，无有暂时闲。"]},{"t":"白附鸠","f":"五言绝句","c":["石头龙尾弯，新亭送客渚。","酤酒不取钱，郎能饮几许。"]},{"t":"拔蒲 其一","f":"五言绝句","c":["青蒲衔紫茸，长叶复从风。","与君同舟去，拔蒲五湖中。"]},{"t":"拔蒲 其二","f":"五言绝句","c":["朝发桂兰渚，昼息桑榆下。","与君同拔蒲，竟日不成把。"]},{"t":"作蚕丝 其一","f":"五言绝句","c":["柔桑感阳风，阿娜婴兰妇。","垂条付绿叶，委体看女手。"]},{"t":"作蚕丝 其三","f":"五言绝句","c":["绩蚕初成茧，相思条女密。","投身汤水中，贵得共成匹。"]},{"t":"作蚕丝 其四","f":"五言绝句","c":["素丝非常质，屈折成绮罗。","敢辞机杼劳，但恐花色多。"]},{"t":"陈太庙舞辞七首 其一 凯容舞","f":"古风","c":["于赫皇祖，宫墙高嶷。","迈彼厥初，成兹峻机。","缦乐简简，閟寝翼翼。","祼飨若存，惟灵靡测。"]},{"t":"陈太庙舞辞七首 其二 凯容舞","f":"古风","c":["昭哉上德，浚彼洪源。","道光前训，庆流后昆。","神猷绵邈，清庙斯存。","以享以祀，惟祖惟尊。"]},{"t":"陈太庙舞辞七首 其三 凯容舞","f":"古风","c":["选辰崇飨，饰礼严敬。","靡爱牲牢，兼馨粢盛。","明明烈祖，龙光远映。","肇我王风，形斯舞咏。"]},{"t":"陈太庙舞辞七首 其四 凯容舞","f":"古风","c":["道遥积庆，德远昌基。","永言祖武，致享从思。","九章停列，八舞回墀。","灵其降止，百福来绥。"]},{"t":"陈太庙舞辞七首 其五 凯容舞","f":"古风","c":["肇迹缔基，义标鸿篆。","恭惟载德，琼源方阐。","享荐三清，筵陈四琏。","增我堂构，式敷帝典。"]},{"t":"陈太庙舞辞七首 其六 景德凯容舞","f":"古风","c":["皇祖执德，长发其祥。","显仁藏用，怀道韬光。","宁斯閟寝，合此萧芗。","永昭贻厥，还符剪商。"]},{"t":"陈太庙舞辞七首 其七 武德舞","f":"古风","c":["烝哉圣祖，抚运升离。","道周经纬，功格玄只。","方轩迈扈，比舜陵妫。","缉熙是咏，钦明在斯。","云雷遘屯，图南共举。","大定扬越，震威衡楚。","四奥宅心，九畴还叙。","景星出翼，非云入吕。","德畅容辞，庆昭羽缀。","于穆清庙，载扬徽烈。","嘉玉既陈，丰盛斯洁。","是将是享，鸿猷无绝。"]},{"t":"鸟妖诗","f":"五言绝句","c":["独足上高台，茂草变为灰。","欲知我家处，朱门当水开。"]},{"t":"读曲歌八十九首 其十四","f":"五言古诗","c":["桐花特可怜。","愿天无霜雪。","梧子解千年。"]},{"t":"读曲歌八十九首 其六十二","f":"五言绝句","c":["执手与欢别，合会在何时。","明灯照空局，悠然未有期。"]},{"t":"齐南郊光章十三首 其七 文德宣烈乐","f":"古风","c":["营泰畤，定天衷。","思心绪，谋筮从。","田烛置，爟火通。","大孝昭，国礼融。"]},{"t":"齐鼙舞曲三首 其一 明君辞","f":"五言古诗","c":["明君创洪业，盛德在建元。","受命君四海，圣皇应灵乾。","五帝继三皇，三皇世所归。","圣德应期运，天地不能违。","仰之弥已高，犹天不可阶。","将复结绳化，静拱天下齐。"]},{"t":"王劭引枯树歌","f":"古风","c":["老子庙前古枯树。","东南枝如伞。","圣主从此去。"]},{"t":"长白山歌","f":"七言绝句","c":["长白山头百战场，十十五五把长枪。","不畏官军十万众，只怕荣公第六郎。"]},{"t":"炀帝梦二竖子歌","f":"古风","c":["住亦死。","去亦死。","未若乘船渡江水。"]},{"t":"汨罗土人为屈原歌","f":"五言古诗","c":["何由得渡湖。"]},{"t":"文中子梦颜子援琴歌","f":"古风","c":["礼乐既正。","诗书既成。","赞明易道。","聿修玄经。","归休乎。","何必永厥龄。"]},{"t":"柳彧上表引歌谣","f":"五言古诗","c":["老禾不早杀，馀种秽良田。"]},{"t":"选人为辛亶歌","f":"古风","c":["辛亶去。","吏部明。","开贤路。","遇太平。","今年定知不可得。","后岁仍期更入京。"]},{"t":"炀帝时并州童谣","f":"古风","c":["一张纸。","两张纸。","客量小儿作天子。"]},{"t":"炀帝时童谣","f":"五言古诗","c":["萧萧亦复起。"]},{"t":"隋末江东童谣","f":"五言绝句","c":["江水保泠泠，杨柳何青青。","人今正好乐，已复戍彭城。"]},{"t":"大业长白山谣","f":"古风","c":["长白山前知世郎。","纯著红罗绵背裆。","长槊侵天半。","轮刀耀日光。","上山吃獐鹿。","下山吃牛羊。","忽闻官军至。","提刀向前荡。","譬如辽东死。","斩头何所伤。"]},{"t":"长安为崔弘度屈突盖语","f":"五言绝句","c":["宁饮三升醋，不见崔弘度。","宁炙三斗艾，不逢屈突盖。"]},{"t":"相州百姓为樊叔略语","f":"古风","c":["智无穷清乡公。","上下正。","樊安定。"]},{"t":"时人为刘昉郑译语","f":"古风","c":["刘昉牵前，郑译推后。"]},{"t":"幽州为卢昌衡卢思道语","f":"古风","c":["卢家千里。","释奴龙子。"]},{"t":"时人为保妥萧慎语","f":"古风","c":["世有两隽。","白杨何妥。","青杨萧慎。"]},{"t":"时人为崔儦李若语","f":"古风","c":["京师灼灼。","崔儦李若。"]},{"t":"邺下为释灵裕语","f":"古风","c":["衍法师伏道不伏俗。","裕法师道俗俱伏。"]},{"t":"谭公府中为裴镜民语","f":"七言古诗","c":["令德日新裴镜民。"]},{"t":"刘炫引谚论政敝","f":"五言古诗","c":["老吏抱案死。"]},{"t":"时人为库狄士文语","f":"五言绝句","c":["刺史罗刹政，司马蝮蛇瞋。","长史含笑判，清河生吃人。"]},{"t":"王子思归歌","f":"楚辞体","c":["洞庭兮木秋。","涔阳兮草衰。","去千乘之家国。","作咸阳之布衣。"]},{"t":"祠洛水歌","f":"古风","c":["洛阳之水，其色苍苍。","祠祭大泽，倏忽南临。","洛滨醊祷，色连三光。"]},{"t":"古歌","f":"七言古诗","c":["边城晏闻汉阳掺。","黄尘萧萧白日暗。"]},{"t":"出塞","f":"五言绝句","c":["候骑出甘泉，奔命入居延。","旗作浮云影，阵如明月弦。"]},{"t":"项王歌","f":"五言古诗","c":["无复拔山力，谁论盖世才。","欲知汉骑满，但听楚歌哀。","悲看骓马去，泣望舣舟来。"]},{"t":"于阗采花","f":"五言绝句","c":["山川虽异所，草木尚同春。","亦如溱洧地，自有采花人。"]},{"t":"沐浴子","f":"五言绝句","c":["澡身经兰泛，濯发傃芳洲。","折荣聊踯躅，攀桂且淹留。"]},{"t":"泽雉","f":"五言绝句","c":["擅场延绣颈，朝飞弄绮翼。","饮啄常自在，惊雄恒不息。"]},{"t":"黄门倡歌","f":"五言古诗","c":["佳人俱绝世，握手上春楼。","点黛方初月，缝裙学石榴。","君王入朝罢，争竞理衣裘。"]},{"t":"隋故太原王夫人墓志铭","f":"古风","c":["屹然孤坟，南阜之墩。","殒我慈母，苍天不仁。","涧水夜流，松烟昼昏。","□□涟洏，暮暮晨晨。"]},{"t":"前陈散骑侍郎刘府君墓铭并序","f":"古风","c":["羡乎元族，厥裔彭徐。","膺灵启业，秉玺神书。","传符永代，独擅邦除。","先根氓主，末叶斯□。","可伤黔□，□愧皇墟。","古今乃异，盈长空无。","瑞□上纪，凡挟嚣愚。","昔食九土，昔食九士。","令□□□，所莅唯守。","所宰唯令，五等相仍，无期九命。","钦咨散骑，水洁璆辉。","州里崇仁，朝敦君子。","德俦菹溺，行侪□李。","文秀长卿，武该樊杞。","献秩孔臧，林茅悊士。","天禄阡沦，归□窀里。","岁月久长，靡言回纪。"]},{"t":"大隋仪同三司建州刺史故徐君墓志铭","f":"古风","c":["崇基负海，建国□□。","遗□后嗣，留爱于民。","兴王启霸，世属功臣。","攀龙矫足，高蹈燕秦。","美矣高□，华哉盛族。","馀庆必隆，挺兹岳牧。","无遗两□，有荣五服。","负石沉江，嗽流岩谷。","公之诞嗣，荫□馀荣。","承家主奠，实彼高明。","敦崇礼让，修拭身名。","诗骚散志，风月吟情。","冽□□朝，位隆二国。","吏仰其威，民思其德。","卷舒图史，遨游儒墨。","道□南容，□逾□北。","方城刺举，求瘼帷褰。","衢奔竹马，水涸贪泉。","慈仁孝悌，公亦有焉。","九皋□响，声闻于天。","梁木横□，太山其颓。","哲人萎矣，呜呼哀哉。","悲风满□，愁云□开。","泪将花堕，鸟共声哀。","素车同萃，白马俱来。","挂剑空存，悬□徒在。","□返北城，□旋南海。","芳林欲正，□风无改。","孝子欲养，慈亲不在。"]},{"t":"玄卿镜铭","f":"古风","c":["日初升，月初盈。","纤翳不生，肖兹万形。","是曰撄宁，瑩虚太清。"]},{"t":"寿阳乐","f":"古风","c":["可怜八公山。","在寿阳。","别后莫相忘。","东台百馀尺。","凌风云。","别后不忘君。","梁长曲水流。","明如镜。","双林与郎照。","辞家远行去。","空为君。","明知岁月驶。","笼窗取凉风。","弹素琴。","一叹复一吟。","夜相思。","望不来。","人乐我独愁。","长淮何烂漫。","路悠悠。","得当乐忘忧。","上我长濑桥。","望归路。","秋风停欲度。","衔泪出伤门。","寿阳去。","必还当几载。"]},{"t":"洛中童谣二首","f":"古风","c":["三月末。","四月初。","杨灰簸土觅真珠。","头去项，脚根齐。","驱上树，不须梯。"]},{"t":"共戏乐","f":"七言律诗","c":["齐世方昌书轨同。","万宇献乐列国风。","时泰民康人物盛。","腰鼓铃柈各相竞。","长袖翩翩若鸿惊。","纤腰袅袅会人情。","观风采乐德化昌。","圣皇万寿乐未央。"]},{"t":"时人为何子朗语","f":"古风","c":["东海三何。","子朗最多。","人中爽爽何子朗。"]},{"t":"清河民为宋世良谣","f":"古风","c":["宁度东吴会稽。","不历成公曲堤。","曲堤虽险贼何益。","但有宋公自屏迹。"]},{"t":"钜鹿公主歌辞","f":"七言古诗","c":["官家出游雷大鼓。","细乘犊车开后户。","车前女子年十五。","手弹琵琶玉节舞。","钜鹿公主殷照女。","皇帝陛下万几主。"]}]};